            "сховай ягоди: {name} уже облизується.",
            "",
            "@місце",
            "{biome_here_in} кожен кущ має зуби.",
            "{biome_here_in} давно ніхто не співав. Не починай.",
            "{biome_here_in} колись билися. Переможені — під ногами.",
            "{biome_here_in} повітря важке. Не сопи.",
            "{biome_here_in} сліди. Не твої. Більші.",
            "{biome_here_in} зі стежки не сходь. Я сказав.",
            "~1 {biome_here_in} тобі не місце. Ну, йди, йди.",
            "~2 {biome_here_in} ми вже були. Ти тоді вт{ік|екла}.",
            "~3 {biome_here_in} з тобою не страшно. Ну, майже.",
            "~3 {biome_here_in} гарно, коли не кусають.",
            "",
            "@місце_кінець",
            "Дивись під ноги.",
            "Не шуми.",
            "~1 І не лізь, куди не треба.",
            "~3 Не дурій.",
            "",
            "@рани",
            "кульгаєш, бачу.",
            "кров на землі. Твоя.",
            "блід{ий|а}, як сніг.",
            "хитаєшся. Я теж.",
            "~1 вовки вже облизуються на тебе.",
            "~1 ще удар — і пісня про тебе буде на два рядки.",
            "~2 рани глибокі. Я не жартую.",
            "~3 мені за тебе страшно. Не смій.",
            "",
            "@рани_порада",
            "Сховайся.",
            "Перев'яжися.",
            "Вогонь і їжа — зараз.",
            "~1 Геройство не твоє.",
            "~2 Відступи. Не соромно.",
            "~3 Бережи шкуру. Іншої нема.",
            "",
            // the talks between the ravens: new threads for the thin ones (an opening, the answers, the end, by ^thread)
            "@х_гроза",
            "^storm.молот Чуєш? То Мйольнір. Тор когось лупить.",
            "^storm.дерево Не сідай на високе дерево, Муніне. Сьогодні не той день.",
            "^storm.злива Ллє так, ніби в Асгарді перекинули діжку.",
            "^storm.страх Ти тремтиш, Муніне? Чи то вітер?",
            "^storm.рахувати Рахуй від спалаху до грому. Так знаєш, як далеко.",
            "^storm.іскра Пір'я аж тріщить. Небо повне іскор.",
            "^storm.тролі У грозу навіть тролі ховаються. Розумні тролі.",
            "^storm.після Після грози повітря чисте. Аж дихати хочеться.",
            "",
            "@х_гроза_кінець",
            "^storm.вищий Вищий, бо розумніший. Блискавка таких поважає.",
            "^storm.злішим Злішим уже нікуди.",
            "^storm.злішим Тоді хай б'є в мене. Тобі вже досить.",
            "^storm.сердитий Тоді вас двоє. Я сховаюсь.",
            "^storm.сердитий А те, що в неба є блискавки. А в тебе — тільки дзьоб.",
            "^storm.набрид Чуєш? Знову гримить. На тебе.",
            "^storm.набрид Небо мене слухає. Тебе — терпить.",
            "^storm.за_тебе Полечу — то разом із тобою. Ти ж тримаєшся.",
            "^storm.за_тебе Хитро. Тільки я легший. Полетимо обидва.",
            "^storm.співаю Співаєш ти гірше за вітер.",
            "^storm.співаю Не подобається. Вітер хоч колись ущухне.",
            "^storm.аби_не_нас Тор б'є, кого хоче. Краще не потрапляй йому на очі.",
            "^storm.аби_не_нас Не нас. Поки ти мовчиш.",
            "^storm.махач Він тебе візьме. Замість молота.",
            "^storm.махач Тор тебе й не помітить. Як блоху.",
            "^storm.цар Цар мокрий і тремтить. Царство під стать.",
            "^storm.цар Сиди, царю. Тільки голову не задирай.",
            "^storm.де_хочу Сміливий ти, доки не загримить.",
            "^storm.де_хочу Спробує. Вона не питає.",
            "^storm.рюмсає Ні. Він плаче, що в нього є ти. Теж.",
            "^storm.рюмсає Тоді він рюмсає за двох. І про тебе — гірше.",
            "^storm.мокріше Мокрі обидва. Хоч у чомусь рівні.",
            "^storm.мокріше Є куди. Я покажу тобі калюжу.",
            "^storm.злість Звісно. Я так і подумав.",
            "^storm.злість Від злості. І трохи від грому. Ну-ну.",
            "^storm.вітер_тіко Відчепився. Але крило поруч, якщо що.",
            "^storm.вітер_тіко Трохи грому — це чесно. Ціную.",
            "^storm.близько Два. Отже, пригнись. Негайно.",
            "^storm.близько Близько. Тому й кажу: сиди нижче.",
            "^storm.до_трьох Тоді просто пригнись. Це вміють усі.",
            "^storm.до_трьох До трьох вистачить. Далі грім уже не страшний.",
            "^storm.тріщу Тріщи тихіше. Ще блискавку приманиш.",
            "^storm.тріщу Тоді не злися. Хоч сьогодні. Для безпеки.",
            "^storm.блищу Красень. Поки не засмажився.",
            "^storm.блищу Блищиш. Блискавка теж помітила.",
            "^storm.грибів Розумніші за тебе. Вони ховаються.",
            "^storm.грибів Розумні, бо ховаються. Ти — ні.",
            "^storm.тупіші Тролі розумніші за нас. Це вже щось про нас каже.",
            "^storm.тупіші Не ми. Ти. Я давно під каптуром у {name}.",
            "^storm.смердить Дихай, Муніне. Хоч раз — свіжим.",
            "^storm.смердить Тобі нормально. Тому від тебе й смердить.",
            "^storm.гриби Не нагадуй. Я досі чую ту пісню.",
            "^storm.гриби Тоді гриби — тобі. Заспіваєте разом.",
            "",
            "@х_світанок",
            "^dawn.птахи Птахи співають. Світ прокидається.",
            "^dawn.мряка Ранкова мряка над землею. Як молоко.",
            "^dawn.сніданок Що на сніданок, Муніне? Знову чиєсь око?",
            "^dawn.асгард Мені наснився Асгард. А тобі що снилося?",
            "^dawn.холод Ранок холодний. Пір'я ще не прогрілося.",
            "^dawn.план Новий день. Який у нас план?",
            "^dawn.лінь Вставай, Муніне. Ти спиш з розплющеним оком.",
            "^dawn.перший Хто перший побачив сонце — тому й день вдалий.",
            "",
            "@х_світанок_кінець",
            "^dawn.то_ти Чув увесь табір. І сусідній.",
            "^dawn.то_ти Зле немовля, що хропе. Рідкісний звір.",
            "^dawn.сторожу Наторожив. Усі вовки розбіглися.",
            "^dawn.сторожу Сторожиш так, що не спить ніхто.",
            "^dawn.мокрі_лапи Мокрі ноги — дрібниця. Твоя пика зранку — от поганий знак.",
            "^dawn.мокрі_лапи По-моєму, так. Мокрий, зате живий.",
            "^dawn.сніданок {name} нагодує. Просто прокинься чемно.",
            "^dawn.сніданок Для тебе всі знаки — про їжу.",
            "^dawn.пощастило Воно далеко. А ти поруч. Тобі не пощастило.",
            "^dawn.пощастило Сонце все чує. Просто мовчить. Вчися.",
            "^dawn.подрімаю Не проспи день. Він короткий.",
            "^dawn.подрімаю Ще хвилинка — і я тебе дзьобну.",
            "^dawn.зжер Ти вже прокинувся. На жаль.",
            "^dawn.зжер З'їж одного. Інші співатимуть про тебе.",
            "^dawn.горлають Прокинешся — вони замовкнуть. Від жаху.",
            "^dawn.горлають Як слід ти не прокидаєшся ніколи.",
            "^dawn.м'ясо Поетичності в тобі — як у каменя.",
            "^dawn.м'ясо Ти навіть у хмарі бачиш котлету.",
            "^dawn.потіє Земля потіє — гарно сказав. Ти теж поет. Поганий.",
            "^dawn.потіє Від мене земля хоч не тікає. Від тебе — так.",
            "^dawn.делікатес Шарю досить, щоб не їсти очей.",
            "^dawn.делікатес Делікатес. Тоді ділись. Ні, жартую.",
            "^dawn.нічо Дадуть. Якщо ти зранку нікого не обматюкаєш.",
            "^dawn.нічо Нічого — теж сніданок. Для філософів.",
            "^dawn.заткнувся Сни не збуваються. Тобі не пощастило.",
            "^dawn.заткнувся Не звикай. Я вже прокинувся.",
            "^dawn.кров Сни в тебе, як і ти. Нічого світлого.",
            "^dawn.кров Мені — Асгард, тобі — бойня. Справедливо.",
            "^dawn.шия Ясно. Впритул — це тільки ти вмієш.",
            "^dawn.шия Дякую. Не впритул. Майже.",
            "^dawn.злий Сонце пригріє. І тебе, і твою вдачу.",
            "^dawn.злий Отже, звичайний день.",
            "^dawn.вгасити Ну, хоч послідовно.",
            "^dawn.вгасити Кого — вирішить {name}. Ти тільки кричи.",
            "^dawn.без_плану Вкурив. Тому й живемо так.",
            "^dawn.без_плану Без плану — це твій план уже років десять.",
            "^dawn.талант Пасеш. Хроплячи.",
            "^dawn.талант Талант. Тільки вчора ти пропас вовка.",
            "^dawn.хвилинку Ще хвилинка — і я тебе дзьобну. Рахую.",
            "^dawn.хвилинку Дві хвилинки. Потім співатиму.",
            "^dawn.гівно Ти побачив — і вже зіпсував.",
            "^dawn.гівно Поганий, бо ти так вирішив ще до сніданку.",
            "^dawn.фартовий Щастя спільне. Навіть тобі шматок.",
            "^dawn.фартовий Фартовий — бо сидиш поруч зі мною.",
            "",
            "@х_вечір",
            "^dusk.кажани>dusk.мозок Кажани їдять комарів. А ти що їси? Мені мозок.",
            "^dusk.сови>dusk.мудрі Сови мудрі. Тому ти їх і не любиш.",
            "^dusk.сови>dusk.поділ Сови вночі, ми вдень. Чесний поділ.",
            "^dusk.багаття>dusk.гарчи Розпалить {name}. Ти тільки сиди й гарчи.",
            "^dusk.багаття>dusk.дзьоб Вогонь буде. Ти тільки не сунь у нього дзьоба.",
            "^dusk.втома>dusk.взаємно Взаємно, Муніне. Взаємно.",
            "^dusk.втома>dusk.завтра Відпочинь. Завтра знову втомлюватимешся.",
            "^dusk.тіні>dusk.світло Тому тримаймося світла.",
            "^dusk.тіні>dusk.бійки Хай лізе. Ти ж хотів бійки.",
            "^dusk.зорі>dusk.чемність А я — щоб ти навчився чемності. Обидва не збудуться.",
            "^dusk.зорі>dusk.світять Зорі не виконують бажань. Вони просто світять.",
            "^dusk.підсумок>dusk.живі Зате всі живі. Це теж підсумок.",
            "^dusk.підсумок>dusk.рахуєш Ти рахуєш трупи. Я рахую дні. Обидва — без кінця.",
            "^dusk.виття>dusk.вечерею Кличуть, щоб ми стали вечерею.",
            "^dusk.виття>dusk.не_відповідай Не відповідай їм. Будь ласка.",
            "^dusk.нічліг>dusk.дах Де {name} вирішить. Сподіваюсь, під дахом.",
            "^dusk.нічліг>dusk.дим Під дахом. Я вже бачу дим.",
            "",
            "@х_сніг",
            "^snow.лапи>snow.відмерзнуть Не вовтузься. Відмерзнуть.",
            "^snow.сніжинка>snow.втомилася Вона просто втомилася. Як усі, хто поруч із тобою.",
            "^snow.сніжинка>snow.не_вміє Сніжинка не вміє зневажати. На відміну від тебе.",
            "^snow.сліди>snow.обережно Тому йдемо обережно. І ти не тупцюй.",
            "^snow.сліди>snow.хто_йде Зате видно, хто за нами йде.",
            "^snow.вогонь>snow.мудрість Мудрість теж гріє. Зсередини.",
            "^snow.вогонь>snow.скоро Скоро. {name} вже шукає, де розпалити.",
            "~3 ^snow.вогонь>snow.скоро Скоро. А поки грійся об мене. Мудрість додаю безкоштовно.",
            "^snow.вовки>snow.чесніші Злі, як ти. Тільки чесніші.",
            "^snow.вовки>snow.тихо Тихо. Не кличмо їх.",
            "^snow.бурулька>snow.для_тебе Найнебезпечніша зброя Мідґарду. Для тебе самого.",
            "^snow.бурулька>snow.відламаєш Не махай нею. Відламаєш.",
            "^snow.глухо>snow.корисне Нарешті щось корисне від снігу.",
            "^snow.глухо>snow.найгарніша Тиша в снігу — найгарніша тиша. Не псуй.",
            "^snow.гори>snow.міцніші Ті, хто міцніший за тебе.",
            "^snow.гори>snow.кози Кози. І трохи вовків. І ми зараз.",
            "^snow.кожух>snow.пір'я Пір'я тепліше, ніж здається.",
            "^snow.кожух>snow.під_комір Сховайся під комір. Там тепло.",
            "",
            "@х_руда",
            "^mine.глибина>mine.привіт Тоді передамо привіт.",
            "^mine.глибина>mine.обережно Гель руду не віддає. Тому й копаємо обережно.",
            "^mine.кайло>mine.смішать Тупе кайло теж копає. А мої жарти — смішать.",
            "^mine.кайло>mine.ниє Нагостримо його. Бо Мунін ниє.",
            "^mine.мідь>mine.пил_тобі Лишиться пил. Блискучий.",
            "^mine.мідь>mine.спокій З міді — бронза. З бронзи — сокира. З сокири — твій спокій.",
            "^mine.обвал>mine.сподіваюсь Не завалиться. Сподіваюсь.",
            "^mine.обвал>mine.заблукаєш Вилетиш і заблукаєш. Як завжди.",
            "^mine.жила>mine.не_їдять Руду не їдять, Муніне.",
            "^mine.жила>mine.вкрадеш Гарна. Не торкайся, бо вкрадеш.",
            "^mine.піт>mine.поважай Це чесний піт. Поважай.",
            "^mine.піт>mine.злети Хочеш — злети. Ніхто не тримає.",
            "^mine.камінь>mine.накликай Дракони живуть вище. Не накликай.",
            "^mine.камінь>mine.битися Тобі б тільки битися.",
            "^mine.пітьма>mine.смолоскип Смолоскип є. Ідей — теж.",
            "^mine.пітьма>mine.світять Мої ідеї світять. Просто тобі не видно.",
            "~3 ^mine.обвал>mine.сподіваюсь Не завалиться. А завалиться — я тебе знайду.",
            "~1 ^mine.пітьма>mine.світять Темно тут тільки тобі. Звикай, тобі не вперше.",
            "",
            "@х_риба",
            "^fish.велика>fish.поважай Нарешті хтось більший за тебе. Поважай.",
            "^fish.велика>fish.розумніша Більша — бо розумніша. До тебе не підпливала.",
            "^fish.черв'як>fish.наживка Тоді наживкою будеш ти.",
            "^fish.черв'як>fish.дзьобом З'їси черв'яка — ловитимеш сам. Дзьобом.",
            "^fish.зірвалась>fish.жити Риба теж хоче жити. Як і ти.",
            "^fish.зірвалась>fish.кричи Не кричи. Наступна почує.",
            "^fish.смажити>fish.дикуни Смажити. Ми ж не дикуни.",
            "^fish.смажити>fish.щасливі Тобі сира, {name} — смажена. Всі щасливі.",
            "^fish.поплавець>fish.вітер То вітер. Не галасуй.",
            "^fish.поплавець>fish.сиди Тягне {name}, а не ти. Сиди.",
            "^fish.чекати>fish.нема_терпіння Рибалка — то терпіння. У тебе його нема.",
            "^fish.чекати>fish.мовчи Мовчи, і вона прийде.",
            "^fish.кістка>fish.жадібно Не жери так жадібно.",
            "^fish.кістка>fish.покарання Це покарання. За жадібність.",
            "^fish.глибоко>fish.перевіряти Кажуть. Не будемо перевіряти.",
            "^fish.глибоко>fish.воронів Є. І вона дуже любить воронів.",
            "~3 ^fish.перша>fish.вдавись Гаразд, перша твоя. Тільки не вдавись.",
            "~3 ^fish.кістка>fish.кашляни Кашляни. Не дам же я тобі здохнути через якусь рибу.",
            "",
            "@х_портал",
            "^portal.світло>portal.заплющ Заплющ очі. Ти й так нічого не хочеш бачити.",
            "^portal.світло>portal.шлях Сліпить, бо там шлях між світами.",
            "^portal.шум>portal.совість Це твоя совість. Вперше озвалась.",
            "^portal.шум>portal.минеться Минеться. Головне — всі на місці.",
            "^portal.рахунок>portal.рахую Багато. Я рахую.",
            "^portal.рахунок>portal.лаявся Більше, ніж ти лаявся. Ну, майже.",
            "^portal.половина>portal.дві Дві. Як і було.",
            "^portal.половина>portal.розум Лапи на місці. Розум — як і раніше, ні.",
            "^portal.звідки>portal.дім З дому. Пам'ятай хоч це.",
            "^portal.звідки>portal.бурчав Звідти, де ти знову бурчав.",
            "^portal.магія>portal.майстри Не Локі. Давні майстри.",
            "^portal.магія>portal.зламаються Якщо Локі — то вони точно колись зламаються.",
            "^portal.мороз>portal.нічого Бо там нічого нема. Навіть тебе.",
            "^portal.мороз>portal.затримуємось Тому й не затримуємось.",
            "^portal.метал>portal.лайка Портал не любить метал. Як я — твою лайку.",
            "^portal.метал>portal.боги Боги так вирішили. Не сперечайся.",
            "",
            "@х_вага",
