            "~1 ^gap_m.чесний|gap_m.годує|gap_m.росте|gap_m.позаду|gap_m.любить>gap_m.випрошую Попереду? Ти просто швидше випрошуєш.",
            "~3 ^gap_m.чесний|gap_m.годує|gap_m.росте|gap_m.позаду|gap_m.любить>gap_m.наздожену Гаразд. Сьогодні твоя перемога. Завтра побачимо.",
