            "@х_рубка",
            "^chop.білка Білка з того дерева втекла. Дивилась на нас, як на вбивць.",
            "^chop.смола Смола на пір'ї. Тепер я пахну лісом.",
            "^chop.пеньок Від дерева лишився пеньок. Як від твого терпіння.",
            "^chop.гнізда На цьому дереві були гнізда. Чужі, на щастя.",
            "^chop.стук Тук-тук. Як серце лісу.",
            "^chop.старе Це дерево старше за нас обох. Було.",
            "^chop.кора Кора тріщить, як старий корабель.",
