            "@х_рубка_кінець",
            "^chop.зжеру Білка жива — і то добре. Хай так і буде.",
            "^chop.рюмсає Рюмсає — на моє пір'я. Відмиватися будемо довго.",
            "^chop.пеньок_діло Сідай. Тільки друге — не при мені.",
            "^chop.сміливіше Сміливо рубати чужі гнізда. Твоя мораль.",
            "^chop.башка Тук-тук. І ще раз. І ще.",
            "^chop.трухляве Шануй старших, Муніне. Навіть дерева. І жарти.",
            "^chop.шо_вийде Дрова — найчесніша доля.",
            "^chop.хай_приходять Прийдуть — то не скаржся.",
            "^chop.дрова_треба Тобі тепло, лісу — сльози. Чесний обмін.",
            "^chop.осика На дубах? Ти з кущів не вилазиш.",
            "^chop.плече Подають — бо ти дзьобаєш, поки не подадуть.",
            "^chop.плече Подають. А ти й не дякуєш.",
            "^chop.по_тобі Я ж казав «берегись». Я завжди кажу.",
            "^chop.ржачно Ржачно — поки не на тебе.",
            "^chop.ржачно Тобі смішно все, що падає. Крім тебе самого.",
