            "^chop.припреться Хай приходить. Дров вистачить навіть на твоє ниття.",
            "^chop.ухиляюсь По-бойовому. З тріскою в пір'ї.",
            "^chop.ухиляюсь Ухиляйся. Тільки не в мій бік.",
            "^chop.хто_кинув Кинула сокира. Вбивай сокиру.",
            "^chop.вбивці Вбивці дерев. Звучить майже гордо.",
            "^chop.вбивці Тобі б тільки титул. Хоч який.",
            "^chop.зжеру Білка тебе обжене по колу. Двічі.",
            "^chop.злість Це не злість. Це ти не митий.",
