            "^chop.башка У тебе в башці стукає, бо там порожньо. Луна.",
            "^chop.трухляве Мої жарти хоч доживають до старості. Твої дохнуть одразу.",
            "^chop.колода Ти вже колода. Тільки балакуча.",
