            "^dungeon.цить Перший гляне {name}. Ти — другий. Може.",
            "^dungeon.цить Цить — то не твоє. {name} вже почу{в|ла}.",
            "^dungeon.голова Від мудрості не роздувається. Тобі не загрожує.",
            "^dungeon.голова Хоч щось у мене велике. А в тебе — тільки дзьоб.",
            "^dungeon.махай Тоді не крутись. Ти мені в око пером тицьнув.",
            "^dungeon.махай Мовчи і терпи. Вийдемо — тоді махай.",
            "^dungeon.щурі Ти й про щурів дбаєш. Зворушливо.",
            "^dungeon.щурі Щурам бенкет. Тобі — заздрість.",
            "^dungeon.без_воронів Ми не скінчимо. Не сьогодні.",
            "^dungeon.без_воронів Вперше кажеш щось розумне. Запишу.",
            "^dungeon.жеру Тоді жуй тихіше. Їх тут сотні.",
            "^dungeon.жеру Їж павуків, але дивись, куди {name} ступає.",
            "^dungeon.пошкодує Павук — може. Я виплутувати не буду.",
            "^dungeon.пошкодує Заплутаєшся — то хоч помовчиш.",
            "^dungeon.черга Приємно бути першим. Хоч десь.",
            "^dungeon.черга Добре, що хоч черга є. Порядок.",
            "^dungeon.поради Зате корисно. Як вода.",
            "^dungeon.поради Кап. Кап. Тепер мене дратуєш ти.",
            "^dungeon.ламай Ламатиме {name}. Ти — порадиш.",
            "^dungeon.ламай Цікаве й страшне — для тебе одне й те саме.",
            "^dungeon.страшне Злякався? Вперше чую.",
            "^dungeon.страшне Підемо, коли {name} захоче. Не ти.",
            "^dungeon.плітки Про мене хоч є що сказати.",
            "^dungeon.плітки Тихіше. Хай пліткують без нас.",
            "^dungeon.нечую Не чуєш, бо сам шумиш.",
            "^dungeon.нечую Не ссикло. Просто глухий.",
            "^dungeon.перший Ступатиме {name}. Обережно.",
            "^dungeon.перший Я лечу. Дурні тут інші.",
            "^dungeon.над А {name} — ні. Тож дивись під ноги за {нього|неї}.",
            "^dungeon.над Поки {name} не наступить. Тоді й ти полетиш.",
            "^dungeon.затхлятина Ти дивний навіть для ворона.",
            "^dungeon.затхлятина Нюхай. Тільки не облизуйся.",
            "^dungeon.дихай Говоритиму стільки, скільки треба.",
            "^dungeon.дихай Вийдемо — тоді й поговоримо. Про твої манери.",
            "^dungeon.ліво Ніби. Я пам'ятаю за нас обох.",
            "^dungeon.ліво Право, ліво, право. Але близько.",
            "^dungeon.житимем Житимеш сам. Я — з {name}.",
            "^dungeon.житимем Золото не їстівне, Муніне.",
            "^dungeon.почув Дотепно. Майже.",
            "^dungeon.почув Тебе він теж не чув. Двічі пощастило.",
            "^dungeon.знає Дякую, Муніне. Тепер мені моторошно.",
            "^dungeon.знає Знає, де вихід. Але не скаже.",
            "",
            "@х_перехід",
            "^cross_h.звірина Тут інша звірина. Глянь на сліди.",
            "^cross_h.барви Навіть світло тут інше. Барви не ті.",
            "^cross_h.подих Вітер тут дме з іншого боку. Як і ти.",
            "^cross_h.бували Ми тут бували раніше. Пам'ятаєш?",
            "^cross_h.від {from_in} було спокійніше. А тут — побачимо.",
            "^cross_h.карта Запам'ятай, де межа. Повертатися будемо.",
            "^cross_h.пташки Птахи тут співають інакше. Прислухайся.",
            "^cross_h.нове {biome_here}. Нове завжди небезпечне.",
            "",
            "@х_перехід_відповідь",
            "^cross_m.нюх>cross_m.нюх_отрути Нові смаки — нові отрути. Не все їж.",
            "^cross_m.нюх>cross_m.нюх_тицяй Нюхай. Але дзьобом не тицяй.",
            "^cross_m.стовп>cross_m.стовп_природа Природа ставила. Їй стовпи не потрібні.",
            "^cross_m.стовп>cross_m.стовп_серцем Межі видно серцем, Муніне. Ну, тобі — ні.",
            "^cross_m.тут>cross_m.тут_ненадовго Найзліший тут — ти. І це ненадовго.",
            "^cross_m.тут>cross_m.тут_знайде Не шукай найзлішого. Сам знайде.",
            "^cross_m.назад>cross_m.назад_вперед Назад не підемо. Вперед цікавіше.",
            "^cross_m.назад>cross_m.назад_болото Знайоме болото — теж болото.",
            "^cross_m.погода>cross_m.погода_мокрий Погода не гірша. Ти просто мокрий.",
            "^cross_m.погода>cross_m.погода_звикнемо Звикнемо. Ми до всього звикаємо.",
            "^cross_m.слід>cross_m.слід_біда Великий слід — велика біда. Не кличмо.",
            "^cross_m.слід>cross_m.слід_паща Хочеш подивитися? Подивишся. Звідти, з пащі.",
            "^cross_m.дерева>cross_m.дерева_коріння Криві дерева — прямі коріння.",
            "^cross_m.дерева>cross_m.дерева_рівні Мої поради — найрівніші в Мідґарді.",
            "^cross_m.край>cross_m.край_дорога Краю нема. Є тільки дорога.",
            "^cross_m.край>cross_m.край_досить Край буде. Коли {name} скаже «досить».",
            "",
            "",
            // the talks between the ravens: new threads for fog, night, boss, death, a new land and the fireside
            "@х_туман",
            "^fog.мряка Туман лізе в пір'я. Холодний, як рука драуґра.",
            "^fog.силует Он силует. Дерево чи троль?",
            "^fog.голос Хтось кличе в тумані. Не відповідай.",
            "^fog.тримайся Тримаймося ближче. Тут легко розгубитися.",
            "^fog.вогник Бачиш вогник? Там, у сірому.",
            "^fog.тиша Туман глушить звуки. Навіть твою лайку.",
            "^fog.мокро Туман осідає на пір'я. Скоро будемо важкі, як каміння.",
            "",
            "@х_ніч",
            "~3 ^night.очі>night.курча Світлячки. Сиди, я пильную. І не будь курчам.",
            "^night.зорі>night.романтик Як блохи? Ти романтик, Муніне.",
            "^night.зорі>night.уважніше Це зорі, а не блохи. Подивись уважніше.",
            "^night.сова>night.сторож Сова — нічний сторож. Не чіпай.",
            "^night.сова>night.мудра Сова мудра. Тому ти її й не любиш.",
            "^night.місяць>night.заблукав Місяць світить, щоб ти не заблукав.",
            "^night.місяць>night.не_бери Він на всіх так дивиться. Не бери до серця.",
            "^night.холод>night.шия Притулися до шиї. Там тепліше.",
            "^night.холод>night.вогонь Біля вогню сядемо. Скоро.",
            "~1 ^night.холод>night.вогонь Терпи. Біля вогню відтанеш. Колись.",
            "^night.шурхіт>night.миша Миша. Не дзьобай, вона тобі нічого не зробила.",
            "^night.шурхіт>night.змія Може, змія. Обережно.",
            "^night.сон>night.думаю Не сплю. Думаю.",
            "^night.сон>night.пильную Ворон уночі пильнує. Я пильную.",
            "^night.драуґри>night.смачного Гниле око? Смачного.",
            "^night.драуґри>night.болото Хай лізуть. Ми далеко від болота.",
            "",
            "@х_бос",
            "^boss.пісня Про цей бій складуть пісню. Я вже знаю перший рядок.",
            "^boss.погляд Одін дивиться. Я відчуваю його погляд.",
            "^boss.біль {name} ледь стоїть. Перемога дорого коштувала.",
            "^boss.наступний Хто наступний, як думаєш?",
            "^boss.страх Зізнаюся: на мить мені стало страшно.",
            "",
            "@х_бос_осадити",
            "^boss.впорались_молодці «Трошки» — щедро як на тебе. Приймаю.",
            "^boss.впорались_молодці Запам'ятаю, що ти це сказав. Шкода, без свідків.",
            "^boss.одін_нагорода Одін платить не хробаками. Він платить тим, що ти ще живий.",
            "^boss.одін_нагорода Тобі — хробак. Мені — похвала. Кожному своє.",
            "^boss.одін_найсильніше Він бачив, хто кричав найголосніше. Оце правда був ти.",
            "^boss.одін_найсильніше Найсильніше ти бив крилом мене по голові. Двічі.",
            "^boss.трофей_сидіти Сидітимеш, поки {name} не зжене. Тобто хвилину.",
            "^boss.трофей_сидіти Король на чужій голові. Тобі пасує.",
            "^boss.трофей_очі Очі — частина трофея. Перебʼєшся.",
            "^boss.трофей_очі Бери. Висітиме сліпа голова, і всі знатимуть, хто постарався.",
            "^boss.загинемо_гадав Я гадав правильно. Нам просто пощастило.",
            "^boss.загинемо_гадав Ти бився з моїм хвостом, коли ховався за мене.",
            "^boss.загинемо_безсмертний Безсмертний поки що тільки твій язик.",
            "^boss.загинемо_безсмертний Перевіримо на наступному. Тільки без мене.",
            "^boss.пишаюся_розкис Не розкис. Констатував. А тепер забудь.",
            "^boss.пишаюся_розкис Записуй. Тільки твоє ім'я там буде дрібненько.",
            "^boss.пишаюся_ще_раз Не скажу. Одного разу й так забагато.",
            "^boss.пишаюся_ще_раз Розчув. По тобі видно.",
            "^boss.пишаюся_нікому Нікому. Мені однаково ніхто не повірить.",
            "^boss.пишаюся_нікому Мовчу. Вперше ти просиш тиші.",
            "^boss.шрами_загояться Загояться. Якщо {name} хоч раз поїсть і поспить по-людськи.",
            "^boss.шрами_загояться Аби загоїлися до наступного. Бо наступний буде злішим.",
            "^boss.шрами_клював Лягло від сокири. Ти клював повітря.",
            "^boss.шрами_клював Клював, ага. Переважно мене, коли лякався.",
            "^boss.шрами_пірʼїна {name} у крові, а ти про пір'їну. Тепер ясно, чому з тобою ніхто не дружить.",
            "^boss.шрами_пірʼїна Пір'їна відросте. Совість — ні, бо її й не було.",
            "^boss.тиша_перднув Тепер ясно, чому так тихо. Усі затамували подих.",
            "^boss.тиша_перднув Я вибачаю. Світ — навряд.",
            "^boss.тиша_нудно Нудно тобі ненадовго. Наступний сам тебе знайде.",
            "^boss.тиша_нудно Посидь у тиші. Може, хоч одна думка прилетить.",
            "^boss.пісня_рядок У такий рядок правда не влазить. Закороткий.",
            "^boss.пісня_рядок У моїй пісні ти теж є. У приспіві, під кущем.",
            "^boss.пісня_мʼясо М'ясо ти з'їси за вечір. Пісню пам'ятатимуть сто років.",
            "^boss.пісня_мʼясо Тоді в пісні тебе не буде. Тільки м'ясо.",
            "^boss.пісня_кажи «Ворон кричав, а {name} руба{в|ла}». Здогадайся, хто ворон.",
            "^boss.пісня_кажи Не скажу. Ти переробиш його на лайку.",
            "^boss.погляд_повчиться Вчити бога — сміливо. Дурно, але сміливо.",
            "^boss.погляд_повчиться Одін чекає, коли ти чогось навчишся. Давно чекає.",
            "^boss.погляд_шия Затерпла, бо ти висів на мені весь бій.",
            "^boss.погляд_шия Ні. Він дивиться на тебе. Мені просто незручно поруч.",
            "^boss.біль_ми_ні Ми ні. Цього разу.",
            "^boss.біль_ми_ні Лежить. А {name} хай сяде. Дай {йому|їй} спокій.",
            "^boss.біль_вивалив Ти нічого не платив. Ти дивився.",
            "^boss.біль_вивалив Вивалив би, ага. З чужої кишені, як завжди.",
            "^boss.біль_сядь Вперше з тобою згоден. Сядь, {name}.",
            "^boss.біль_сядь Чуєш, {name}? Навіть Мунін каже сісти.",
            "^boss.наступний_готовий Ти готовий. {name} — ні. Почекаєш.",
            "^boss.наступний_готовий Готовий ти був і цього разу. Під кущем.",
            "^boss.наступний_найбільший Найбільший і тебе склює. Не поспішай.",
            "^boss.наступний_найбільший Буде найбільший. Тоді й побачимо, де твій дзьоб.",
            "^boss.страх_трошки Трошки — це коли тремтить плече. Плече тремтіло.",
            "^boss.страх_трошки Відчепився. Але запам'ятав.",
            "^boss.страх_теж Чесно — це щось новеньке. Мені подобається.",
            "^boss.страх_теж Двоє боягузів на одних плечах. Гарна компанія.",
            "",
            "@х_смерть",
            "^death.валькірії Валькірії вже кружляли. Я бачив їхні крила.",
            "^death.помилка Знаєш, де була помилка? Я знаю.",
            "^death.могила Камінь над могилою. Ще один у нашій колекції.",
            "^death.холод Було холодно там, де ми лежали.",
            "^death.помста Хто це зробив, той ще пожалкує.",
            "^death.знову Ну що, знову з нуля.",
            "",
            "@х_біом",
            "^biome.небо Навіть небо тут іншого кольору.",
            "^biome.рослини Дивні рослини. Не їж нічого, Муніне.",
            "^biome.перші Ми тут перші з воронів. Мабуть.",
            "^biome.тиша Тут тихо по-іншому. Насторожено.",
            "^biome.дім Дім тепер далеко. Чуєш, як далеко?",
            "^biome.скарби Тут має бути щось цінне. Нові землі — нові скарби.",
            "",
            "@х_кінець",
            "^fog.сліпий Тимчасово. Не звикай до компанії.",
            "^fog.сам_засідка Засідка, що лається вголос. Надійно.",
            "^fog.сам_засідка Засідка мовчить. Спробуй хоч раз.",
            "^fog.клюнути Аби цим «кимось» не виявився я.",
            "^fog.клюнути Зненацька клюють і нас. Тихо.",
            "^fog.ти_вже Я знаю, де ми. Просто не кажу.",
            "^fog.ти_вже Заблукав. Разом із тобою. Утіха слабка.",
            "^death.помилка_непопередив Попереджав. Ти тоді якраз жука клював.",
            "^death.помилка_name Помилка — сперечатися з тим, хто тебе носить.",
            "^death.помилка_name {name} помиляється, ти підбадьорюєш. Гарна команда.",
            "^death.помилка_кажи Ти закричав, і воно обернулося. Ось і все.",
            "^death.помилка_кажи Полізли, не роздивившись. Усі троє.",
            "^death.могила_цвинтар Табличку напишу я. Ти пишеш тільки лайкою.",
            "^death.могила_цвинтар Колись їх стане менше. Сподіваюся.",
            "^death.могила_памʼятник Нашій? Твоїй. Я лише стояв поруч.",
            "^death.могила_памʼятник Чесно. Хай стоїть і нагадує.",
            "^death.холод_нехочу Тоді не лізь першим. Нагадаю.",
            "^death.холод_нехочу Не хочеш — то не каркай під руку.",
            "^death.холод_сидів Сидів. Трусився. Я бачив.",
            "^fed_munin.чавк Їж повільніше. Подавишся.",
            "^fed_munin.чавк Тебе й без манер чути аж до Асгарду.",
            "~3 ^fed_munin.чавк Чавкай уже. Аби пішло на користь.",
            "^fed_munin.злий Знаю. Я й не надіявся.",
            "^fed_munin.злий Тоді хоч жуй тихо.",
            "~3 ^fed_munin.злий Ну, смачного. Щиро. Майже.",
            "^fed_munin.крихта Обійдусь. Але запам'ятаю, що пропонував.",
            "^fed_munin.крихта Щедрість у тебе, як та крихта: ледве видно.",
            "~3 ^fed_munin.крихта Дякую. Сьогодні ти майже не свиня.",
            "^fed_munin.зжеру Подавишся. Я жилавий.",
            "^fed_munin.зжеру Спробуй. Я тобі в горлі застрягну.",
            "^gap_h.плює Кажеш так, бо в тебе її нема.",
            "^gap_h.плює Зневажати те, чого не маєш, — твій стиль.",
            "~3 ^gap_h.плює Гаразд. Тільки не заздри так голосно.",
            "^gap_h.вовк Закрив. І потім годину про це кричав.",
            "^gap_h.вовк Один вовк — ще не довіра. Але зараховано.",
            "^gap_h.страшний Страшніший — так. Тому тебе й тримають подалі.",
            "^gap_h.страшний Страх — не довіра. Тебе просто обходять.",
            "^gap_h.молодець Приймаю. Хоч і зі скрипом.",
            "^gap_h.молодець Зазнаватись — твоя робота. Я просто правий.",
            "~3 ^gap_h.молодець Дякую. Бачу, тобі це дорого коштувало.",
            "^gap_h.погроза Погрожуєш — значить, нема чим відповісти.",
            "^gap_h.погроза Пір'я відросте. А довіра в тебе — ні.",
            "^gap_h.голос Голосніший — не значить правий.",
            "^gap_h.голос Голосно — то не довіра. То шум.",
            "^gap_h.бубниш Краще бубніти, ніж верещати над вухом.",
            "^gap_h.бубниш Під мене спиться. Під тебе — тільки здригаються.",
            "^gap_h.протягне Протягне. І виспиться вперше.",
            "^gap_h.протягне Перевіримо. Посидь день мовчки.",
            "^gap_h.наздожену Обіцяєш уже вкотре.",
            "^gap_h.наздожену Наздоганяй. Тільки без плювків.",
            "~3 ^gap_h.наздожену Чекаю. Без тебе там нудно.",
            "^gap_h.нудний Нудний, зате мені вірять.",
            "^gap_h.нудний Пень хоча б не матюкається. Ми з ним схожі.",
            "^gap_h.чесність Чесність без лайки теж буває. Спробуй якось.",
            "^gap_h.чесність Брехунцю вірять. Чесного — терплять. Цікаво, правда?",
            "^fog.одноокий Одним, але більше, ніж ти двома.",
            "^fog.одноокий Йому дрібниця. Нам — ні. Тримайся.",
            "^fog.знайду Знайдеш — дзьобни. Аби знайшов.",
