            "^fog.бійка Не буде. Ти ще не бачив, хто там.",
            "^fog.бійка Бійка в тумані — це коли б'єш своїх. Стій.",
            "^fog.троль Якщо кущ рухається — це не кущ.",
            "^fog.троль Тоді йдемо далі. Обережно.",
