            "^fog.притулися Без ніжностей. Просто тепло. Дякую.",
            "^fog.притулися Притулюсь. Ти теплий, як не дивно.",
            "^fog.троль_сто Твоя печінка вже раз кущ за троля мала.",
            "^fog.троль_сто Підійдемо — побачимо. Обережно.",
            "^fog.дерево Дзьобай. Дерево не відповість.",
            "^fog.дерево Дзьобни. Якщо заверещить — тікаємо.",
            "^fog.матюком Тепер воно знає, де ми. Дякую.",
            "^fog.матюком Туман любить пастки з голосами. А ти — пастка з лайкою.",
            "^fog.гукну Не треба, щоб прибігало. Тихо.",
            "^fog.гукну Туман любить пастки з голосами. Не будь приманкою.",
            "^fog.пазуха У пазуху не пущу. Сиди й не злітай.",
            "^fog.пазуха Плече — це близько. Для тебе — навіть забагато.",
            "^fog.запах Книжками? Ти хоч одну бачив?",
            "^fog.запах А тебе знайде кожен вовк. Так само.",
