            "^fog.курва Чув. На жаль, не заглушило.",
            "^fog.курва Дякую. Тепер нас чують і в Гельгеймі.",
            "^fog.не_подобається Мені подобається. Тихо, як у пір'ї.",
            "^fog.не_подобається Чую. Ледве. От би завжди так.",
            "^fog.злість Злітати буде важко. Сидимо.",
            "^fog.злість Злість хоч не капає за комір.",
