            "^fog.пси Пси обтрушуються. Ворони чекають. Чекай.",
            "^death.холод_сидів Ясно. Чекав і цокотів дзьобом на весь ліс.",
            "^death.помста_очі Виклюєш. Але спершу хай {name} одягнеться.",
            "^death.помста_очі Помстимося. Але з розумом.",
