            "^death.знову_злий Злий — це добре. Злість теж зброя.",
            "^death.знову_злий Голий, босий, але живий. Нуль — не так і мало.",
            "^death.знову_памʼятаємо Ти пам'ятаєш, де їжа. Я — де смерть. Разом упораємось.",
            "^death.знову_памʼятаємо Пам'ятаєш. Дивно, але приємно.",
            "^biome.вбити_пики Пики тут клюються у відповідь. Пам'ятай.",
            "^biome.вбити_пики Клюй. А я рахуватиму, скільки разів ми тікали.",
            "^biome.вбити_спробують Спробують. Вони тут саме для цього.",
            "^biome.вбити_спробують Не кажи цього вголос. Почують.",
            "^biome.вбити_здохнемо Здохнемо, то хоч не від нудьги.",
            "^biome.вбити_здохнемо Може, й ні. Якщо ти хоч раз помовчиш.",
            "^biome.дивись_смердить Тобі подобається все, що смердить. Тому ти й мене не любиш.",
