            "^biome.дивись_як_усюди «Як усюди, тільки інше». Ти щойно описав усі мандри.",
            "^biome.дивись_як_усюди Ти просто не вмієш дивитись.",
            "^biome.дивись_гарно Мовчу. Але запам'ятаю.",
            "^biome.дивись_гарно Мені подобається. І тобі, бачу, теж.",
