            "^biome.дорога_мапа Тоді не загуби свою мапу.",
            "^biome.повітря_недружній Тоді ви з ним порозумієтеся.",
            "^biome.повітря_недружній Знаю. Тому й сиджу на другому плечі.",
            "^biome.повітря_нюхаєш Нюхаю. Тому й досі живий.",
            "^biome.повітря_нюхаєш Хтось мусить нюхати. Ти лише жереш.",
            "^biome.страшно_я_тут Ворухнеться — ти сховаєшся першим. Але дякую.",
            "^biome.страшно_я_тут Добре, що ти тут. Мовчи, що я це сказав.",
            "^biome.страшно_гарно2 Не скажу. Мені однаково ніхто не повірить.",
            "^biome.страшно_гарно2 Мовчу. Хоч страшно — то вже не мені одному.",
            "^biome.звірі_спершуя Спершу ти їх, потім вони тебе. Кругообіг.",
            "^biome.звірі_спершуя Дивись, щоб ми самі не стали тут новою їжею.",
            "^biome.звірі_вкурсі Будуть. Ти кричиш так, що чути аж у сусідньому краю.",
            "^biome.звірі_вкурсі Хай краще не знають. Нам так спокійніше.",
            "^biome.мапа_відступаю Шарю. Красиво відступати теж треба вміти.",
