            "^biome.мапа_смачний Найсмачніший тут, підозрюю, ти.",
            "^biome.мапа_смачний Глянь. Тільки не куштуй усе підряд.",
            "^biome.небо_гівняний Мені подобається. Навіть якщо тобі — ні.",
            "^biome.небо_гівняний Для тебе все погане, крім їжі.",
            "^biome.небо_синє Синє. Але інше синє. Тобі не пояснити.",
            "^biome.небо_синє Сліпий тут один. І це не я.",
            "^biome.рослини_зжер Побачимо, що з тобою буде до ранку.",
