            "^biome.рослини_нежеру Тримаю тебе за слово. І за хвіст.",
            "^biome.перші_наше Чую. Наше, поки нас не з'їли.",
            "^biome.перші_наше Наше. Тільки не міть територію, прошу.",
            "^biome.перші_дурні Дурні, зате перші. Хтось мусить.",
            "^biome.перші_дурні Говори за себе. Я тут, бо {name} сюди піш{ов|ла}.",
            "^biome.тиша_знають Знають. Тепер помовч, щоб і я щось почув.",
            "^biome.тиша_знають Бояться, ага. Сміються, мабуть, у кущах.",
