            "^sail.хитає_хвіст Тримайся за щоглу. І за язик.",
            "^sail.хитає_хвіст Спробуй. Далі попливеш сам.",
            "^sail.хитає_танцюю Танцюй. Тільки не на мене.",
            "^sail.хитає_танцюю Гарно танцюєш. Особливо зеленим кольором.",
            "^sail.борт_дно Мудрість не тоне. Вона спливає.",
            "^sail.борт_дно На дно піде той, хто більше жере. Подумай.",
