            "^sail.чайки_щури Вони тебе теж. Взаємно.",
            "^sail.чайки_заблукали Ми не заблукали. Ми шукаємо.",
            "^sail.чайки_заблукали Хай так. Заблукаємо разом із чайками.",
            "^cross_h.запах_тобою Я пахну розумом. Тобі цей запах незнайомий.",
            "^cross_h.запах_тобою Звикнеш. Ти ж і до себе звик.",
