            "^cross_h.межа_знак Велике — сумнівно. Чорне — так.",
            "^cross_h.додому_тепло Не ржу. У мене теж.",
            "^cross_h.додому_тепло Не ржу. Записую.",
            "^cross_h.додому_пожерти Дадуть. Якщо ти не з'їв усе ще минулого разу.",
            "^cross_h.додому_пожерти Дадуть. А ти хоч раз дай усім виспатися.",
