            "^cross_h.повітря_легкий Пір'їна, яка жере за трьох.",
            "^cross_h.повітря_небезпечно Тобі кайф, поки не болить.",
            "^cross_h.повітря_небезпечно Тоді не розслабляйся. Цей кайф кусається.",
            "^cross_h.звірина_куштував Дивись, щоб вона не скуштувала тебе першою.",
            "^cross_h.звірина_куштував Куштуй обережно. Нове буває отруйним.",
