            "^cross_h.бували_непригадую Цього разу буде краще.",
            "^cross_h.від_мухи Тут мухи не дохнуть. Тут вони кусаються.",
            "^cross_h.від_мухи Мухи хоч не жалілися. На відміну від тебе.",
            "^cross_h.від_завалимо Обережно — і разом.",
            "^cross_h.від_завалимо Завалимо. Тільки не того, хто більший за нас.",
            "^cross_h.карта_носом Шарю. Твій ніс — краща мапа, ніж твоя голова.",
            "^cross_h.карта_носом Шарю. Тільки ти й сам смердиш. Збиваєш.",
            "^cross_h.карта_нажерся Повернемося. Рано чи пізно. Ситим чи ні.",
            "^cross_h.карта_нажерся Наїсишся — тоді й підемо. Тобто ніколи.",
            "^cross_h.пташки_дізнаються Не чіпай. Вони хоча б не лаються.",
            "^cross_h.пташки_дізнаються Хай співають. Хоч хтось тут радіє.",
            "^cross_h.пташки_пузо Твоє пузо співає гірше за них.",
            "^cross_h.пташки_пузо Пузо — теж пташка. Голодна й голосна.",
            "^cross_h.нове_весело Обережно — і разом. Не біжи.",
            "^cross_h.нове_весело Не сцю. Думаю. Тобі таке не знайоме.",
            "^cross_h.нове_ззаду Прикриєш. Як завжди — голосом.",
            "^cross_h.нове_ззаду Здалеку прикривати ти вмієш. Майстер.",
            "^idle_b.сон_одін>idle_b.я_одін Ти — Одін? Тоді світові кінець. Швидкий.",
            "^idle_b.сон_одін>idle_b.я_одін Одін без мудрості. Справді сон.",
            "^idle_b.про_тебе>idle_b.образа Про тебе. Себе я не чую.",
            "^idle_b.про_тебе>idle_b.образа Про того, хто смердить болотом. Вгадаєш з першого разу?",
            "^idle_b.мудрість>idle_b.вухо Моя мудрість — єдине, що тут не смердить.",
            "^idle_b.мудрість>idle_b.вухо Без моєї мудрості ти б давно заблукав. Двічі.",
            "^idle_b.подарунок>idle_b.тримай Подарунок. Такий, що не повернеш.",
            "^idle_b.подарунок>idle_b.тримай Подарунок, авжеж. Без гарантії й без вороття.",
            "^idle_b.книжки>idle_b.пилюка Книжки хоч пахнуть. А ти — смердиш.",
            "^idle_b.книжки>idle_b.пилюка Книжками пахне розум. Тобі незнайомий запах.",
            "^idle_b.пашу>idle_b.розвідка Пашеш? Ти в болоті сидів. Цілий день.",
            "^idle_b.пашу>idle_b.розвідка Робота — це не валятись у болоті.",
            "^idle_b.запиши>idle_b.записуй Для тебе — геніально. Запишу.",
            "^idle_b.запиши>idle_b.записуй Запишу в історію. Під твоїм ім'ям. На ганьбу.",
            "^idle_b.коли>idle_b.колись Коли ж треба? Я чекаю триста років.",
            "^idle_b.коли>idle_b.колись Треба було вчора. І позавчора. Ти проспав.",
            "^idle_b.мудро>idle_b.можу Мудро. Шкода, що сам так не вмієш.",
            "^idle_b.мудро>idle_b.можу Перша розумна річ за твоє життя. Повісимо над жердиною.",
            "^idle_b.почав>idle_b.дражнить Я вже почав. А день досі гарний. Подумай над цим.",
            "^idle_b.почав>idle_b.дражнить Я говорю вже годину. День тримається. Ти — ні.",
            "^idle_b.обіцяв>idle_b.поки Сьогодні. Запам'ятав. Тримаю за дзьоб.",
            "^idle_b.обіцяв>idle_b.поки Обіцянка Муніна. Рідкісний птах.",
            "^idle_b.трошки>idle_b.не_в_рахунок Ну от. Уже трошки зіпсував.",
            "^idle_b.трошки>idle_b.не_в_рахунок Ти й «трошки» не вмієш.",
            "^idle_b.розкис>idle_b.тихіше Не розкисаю. Констатую.",
            "^idle_b.розкис>idle_b.тихіше Розкисати — твоя робота. Я тільки рахую.",
            "^idle_b.кинув>idle_b.мо «Мо'». Оце «мо'» все й каже.",
            "^idle_b.кинув>idle_b.мо Не кинув би. Ти й дороги додому не знаєш.",
            "^idle_b.пісня>idle_b.забудь Пісню не буду. Але віршик уже склав.",
            "^idle_b.пісня>idle_b.забудь Не буду. Але ти сказав «тримаємось». Я чув.",
            "^idle_b.старається>idle_b.брешеш Він старається. Я бачив.",
            "^idle_b.старається>idle_b.брешеш Тому й не кличе назад. Пам'ятає.",
            "^idle_b.тімя>idle_b.боги Ось тому нас і відпустили.",
            "^idle_b.тімя>idle_b.боги Дзьобом Одіна? Я це послухаю здалеку.",
            "^idle_b.наші>idle_b.нікому Оце вперше ти сказав щось правильне.",
            "^idle_b.наші>idle_b.нікому Не кажи цього при Одіні. Він ревнивий.",
            "^idle_b.прийде>idle_b.нарешті Тоді не скаржся, коли воно прийде.",
            "^idle_b.прийде>idle_b.нарешті Добре? Подивимось, що ти скажеш, коли воно прийде.",
            "^idle_b.вигадую>idle_b.погодний Я не вигадую. Я думаю. Відчуй різницю.",
            "^idle_b.вигадую>idle_b.погодний Вітер не бреше. На відміну від тебе.",
            "^idle_b.ближче>idle_b.вдвох Я й так поруч. Ти теж не відставай.",
            "^idle_b.ближче>idle_b.вдвох Тримаюсь. Не тому, що боюсь.",
            "^idle_b.бойовий>idle_b.тактика Бойовий. Останній бій — з гілкою. Гілка виграла.",
            "^idle_b.бойовий>idle_b.тактика Бойовий? Тебе вчора горобець прогнав.",
            "^idle_b.не_там>idle_b.знущаєшся Не там. Ну й хай стирчить. Тобі личить.",
            "^idle_b.не_там>idle_b.знущаєшся Ні, лівіше. Ще лівіше. Тепер ти схожий на їжака.",
            "^idle_b.дивитись>idle_b.відвернись Не питали. Але дивитись мені.",
            "^idle_b.дивитись>idle_b.відвернись Мене ніхто не питає. Тому все й стирчить.",
            "^idle_b.хмара_ти>idle_b.хвалько Зате висока. Тобі не дострибнути.",
            "^idle_b.хмара_ти>idle_b.хвалько Зате біла. А твоя — як сажа.",
            "^idle_b.показав>idle_b.словив Вже показав. Дякую, схоже.",
            "^idle_b.показав>idle_b.словив Не треба. Бачу. Точнісінько як хмара.",
            "^idle_b.голодний>idle_b.нагодуй Ти задумливий, тільки коли голодний.",
            "^idle_b.голодний>idle_b.нагодуй Задумливий? То в тебе пузо бурчить.",
            "^idle_b.тобі>idle_b.забули Я почув. Двічі.",
            "^idle_b.тобі>idle_b.забули Й тобі. Бачиш, не так уже й боляче.",
            "^idle_b.хліб>idle_b.пишайся Розкис. Раз на сто років можна.",
            "^idle_b.хліб>idle_b.пишайся Хліб у пиві. Твоє найкраще порівняння. Пишаюсь.",
            "^idle_b.хворий>idle_b.мутиш Не захворів. Не звикай.",
            "^idle_b.хворий>idle_b.мутиш Здоровий. Просто ти сьогодні менш нестерпний.",
            "^perch_a.нудьга Нудьга — теж сила. Вчися її терпіти.",
            "^perch_a.нудьга Нудно тобі завжди. А сила вертається не завжди.",
            "^perch_a.мясо М'ясо — це теж сила. Тільки не в голову.",
            "^perch_a.мясо У тебе все зводиться до м'яса.",
            "^perch_a.дзьобнути Тільки не мене. Я ще не відпочив.",
            "^perch_a.дзьобнути Збережи на ворогів. Я ж не ворог. Здебільшого.",
            "^perch_a.витікає Логічно. Порожня посудина не тече.",
            "^perch_a.витікає Вперше погоджуюсь. Думати — дороге задоволення.",
            "^perch_a.сиджу Ти сидиш криво. Жердина тримається попри тебе.",
            "^perch_a.сиджу Ото логіка. Тоді й болото рівне, бо ти в ньому сидів.",
            "^perch_a.думки Думки й мають крутитись. Твої просто стоять.",
            "^perch_a.думки Мої думки рівні. Просто тобі за ними не встигнути.",
            "^perch_a.придумав Придумав. Бачиш, яка розумова робота?",
            "^perch_a.придумав Придумав. І ти теж працюєш — просто не знаєш про це.",
            "^perch_a.безробітний Тому ти й безробітний. Тут дзьобати нікого.",
            "^perch_a.безробітний Дзьобни думку. Хоч одну.",
            "^perch_a.повчаєш Повчаю, бо ти слухаєш. Інколи.",
            "^perch_a.повчаєш Нудно? Значить, робота йде. Розумова.",
            "^perch_a.дурне Дурне, але велике. Як ти.",
            "^perch_a.дурне Притягне — ти перший полізеш дивитися.",
            "^perch_a.яма Хата в ямі. Ти б там жив.",
            "^perch_a.яма Не накаркай. Ям тут уже досить.",
            "^perch_a.мовчиш Тоді рай уже був. Ти проспав.",
            "^perch_a.мовчиш Добре, помовчу. Подивимось, скільки ти витримаєш.",
            "^perch_a.втекли Від мене тікають тихо. Від тебе — з криком.",
            "^perch_a.втекли Тоді дякую. Чудова послуга.",
            "^perch_a.зжер Зжерти хочеш ти. Ходи, зжер муху.",
            "^perch_a.зжер Нудно — спи. Рай для сплячих.",
            "^perch_a.посунься Я тут сидів першим.",
            "^perch_a.посунься Посунусь — ти розляжешся на всю.",
            "^perch_a.злітай Злітати мушу я? Логіка товстих.",
            "^perch_a.злітай Не дочекаєшся. Посиджу. Тісно, але принципово.",
            "^perch_a.пхайся Крило не пхається. Воно просто є.",
            "^perch_a.пхайся Я не пхаюсь. Я відвойовую своє.",
            "^perch_a.окей «Окей». Від тебе це як пісня.",
            "^perch_a.окей Запам'ятаю. Рідкісний день.",
            "^perch_a.пиво Тобі не наливали. Ти сам брав.",
            "^perch_a.пиво Пиво буде. Коли заслужиш. Тобто ніколи.",
            "^perch_a.задоволений Цілком. Бачиш, не боляче.",
            "^perch_a.задоволений Задоволений. Тепер скажи це ще раз, повільніше.",
            "^perch_a.почув Пізно. Я вже переказав.",
            "^perch_a.почув Не почує. Я не скажу. Мабуть.",
            "^perch_a.соплі Не рюмсаю. Констатую.",
            "^perch_a.соплі Розкис. Раз на рік можна.",
            "^perch_a.тобі Особливо мені. Хтось же мусить тебе терпіти.",
            "^perch_a.тобі Так. Без тебе я б занудився. Від тиші.",
            "^perch_a.з_тебе Почни. Я гіркий.",
            "^perch_a.з_тебе З мене — тільки пір'я. Подавишся.",
            "^perch_a.завжди Знаю. Тому й не питав, а бачив.",
            "^perch_a.завжди По життю ти — шлунок із крилами.",
            "^perch_a.нікуди Правда. Ми як тінь. Тільки голосніша.",
            "^perch_a.нікуди Без нас {name} уже тричі заблука{в|ла} б.",
            "^perch_a.клюну Знайдеш? Ти себе вранці не знаходиш.",
            "^perch_a.клюну Ото справжня вірність. З дзьобом.",
            "^perch_a.скрипить Скрипить, бо працює. Твоя мовчить.",
            "^perch_a.скрипить Це не скрип. Це ти заважаєш.",
            "^perch_a.дим Не перегріюсь. Ти поруч — охолоджуєш.",
            "^perch_a.дим Від тебе дим не йде давно. Згасло.",
            "^perch_a.лінивий Твій герой. Чомусь не дивно.",
            "^perch_a.лінивий Лінь — мати винаходів. Тобі вже пам'ятник ставити.",
            "^perch_a.корисна Дякую. Майже комплімент.",
            "^perch_a.корисна Тоді й ти колись станеш корисним. Як жердина.",
            "^perch_a.звик Звик. У тебе це найближче до ніжності.",
            "^perch_a.звик Я теж. Важко, але звик.",
            "^perch_a.пристав Помітно. Сиди далі.",
            "^perch_a.пристав Пристав, бо нудно. Ти ж кращий за тишу. Ледь-ледь.",
            "^perch_a.линяю Я не линяю. Я ділюся.",
            "^perch_a.линяю Не на тебе. Повз тебе. Ти просто заважаєш.",
            "^perch_a.лічиш Нема. Я ж на жердині. Ти — моя розвага.",
            "^perch_a.лічиш Лічу. Дев'ять пір'їн ти вже згубив.",
            "",
            "@х_вогонь",
            "^rest_a.зорі Дивись, як зорі над вогнем мерехтять.",
            "^rest_a.мрія Знаєш, про що я мрію? Про тихий дах і повну миску.",
            "^rest_a.одін Цікаво, Одін зараз теж біля вогню сидить?",
            "^rest_a.пісня Заспівати тобі, Муніне? Тихенько.",
            "^rest_a.день Довгий був день. Добре, що закінчився біля вогню.",
            "",
            "@х_тепло",
            "^rest_a.плакав Я хоч плакав тихо. Тебе чув увесь фіорд.",
            "^rest_a.сторожу Як не заснеш. Тобто сторожу я.",
            "^rest_a.сторожу Ти засинаєш раніше, ніж договорюєш «посторожу».",
            "^rest_a.назавжди Забудуть — і годувати перестануть. Подумай ще.",
            "^rest_a.назавжди Назавжди не вийде. Дрова скінчаться.",
            "^rest_a.про_мене Розповів би. Коротко: їв, лаявся, спав.",
            "^rest_a.про_мене Про тебе Одін і так знає. Ти ж кричиш на весь Мідґард.",
            "^rest_a.драуґр Ти драуґра не зробив. Ти на нього накричав.",
            "^rest_a.драуґр Від твоєї версії Одін заснув би ще швидше.",
            "^rest_a.сам Блискуче. Моїм же жартом.",
            "^rest_a.сам Повторив за мною. Уже прогрес.",
            "^rest_a.мороз Тоді грійся. Жартів у мене ще багато.",
            "^rest_a.мороз Ну, хоч щось у тобі я зачепив.",
            "^rest_a.нікому Скажеш — і я розповім, як ти бурульку лизав.",
            "^rest_a.нікому Кажи. Тобі однаково ніхто не вірить.",
            "^rest_a.мені_теж Мовчу. Тепер у нас спільна таємниця.",
            "^rest_a.мені_теж Ясно. Двоє мовчать про одне. Це вже майже дружба.",
            "^rest_a.дзьоб Кінець неправильний. Але смішний.",
            "^rest_a.дзьоб Другий ворон потім довго тікав. Але це вже інша казка.",
            "^rest_a.допер Допер? Так швидко? Казка вже діє.",
            "^rest_a.допер Погана, бо про розумного? Розумію. Не твій жанр.",
            "^rest_a.жар Сунь сам. Ти ж усе перевіряєш дзьобом.",
            "^rest_a.жар Я знаю, що жар. Це називається «порівняння».",
            "^rest_a.хвіст Обережно з хвостом. Він у тебе один.",
            "^rest_a.хвіст Сядуть — будеш найсвітліший ворон Мідґарду.",
            "^rest_a.пика Ось тому веде {name}, а не ти.",
            "^rest_a.пика Просто. Як і ти.",
            "^rest_a.гель У Гель годують. Тобою.",
            "^rest_a.гель Їжа знайдеться. {name} без неї не ходить.",
            "^rest_a.дим Знаю, що дим. Ти вмієш зіпсувати будь-яку ніч.",
            "^rest_a.дим Дякую. Тепер вони просто мерехтять у диму.",
            "^rest_a.мовчи Мовчу. Бо вперше ти маєш рацію.",
            "^rest_a.мовчи Посидимо, поки не згасне. Мовчки.",
            "^rest_a.махач Миска в нас спільна. Решту мрій — окремо.",
            "^rest_a.махач Бочка медовухи і ти. Бідний той махач.",
            "^rest_a.ссикуни Скажеш це під дощем. Я послухаю.",
            "^rest_a.ссикуни Тоді спи надворі. Миску я посторожу.",
            "^rest_a.бухає Не кажи цього при ньому. Він чує крізь вогонь.",
            "^rest_a.бухає Хай п'є. Йому є що забувати. Тебе, наприклад.",
            "^rest_a.думає Думає. Що з тобою робити.",
            "^rest_a.думає Про тебе він теж думає. Зітхаючи.",
            "^rest_a.спробуй Гаразд. Мовчу. Але пісня була б гарна.",
            "^rest_a.спробуй Не відкрию. Заспіваю завтра, коли ти спатимеш.",
            "^rest_a.засну Отже, пісня корисна. Почну.",
            "^rest_a.засну Тоді співатиму довго. Для всіх.",
            "^rest_a.нудний Норм вогонь. Від тебе це похвала.",
            "^rest_a.нудний Завтра буде новий. Може, не такий нудний.",
            "^rest_a.каторга Ти цілий день сидів на плечі. Співчуваю плечу.",
            "^rest_a.каторга Відпочивай. Завтра знову втомлюватимешся.",
            "",
            "@х_вогонь_відповідь",
            "^rest_b.мед>rest_b.вода Мед — для тих, хто заслужив. Тобі — вода.",
