            "^snow.міцніші Та хай живуть. А я хочу додому. Додому, чуєш?",
            "^snow.кози Ми — не по волі. Нас {name} притяг{|ла}.",
            "^snow.кози Кози, бля. Я ще й з козами в одному списку.",
            "^snow.пір'я Пиздиш. Але хай. Мені вже однаково.",
            "^snow.пір'я Тепліше? Чого ж я тоді дзвеню?",
            "^snow.під_комір Пиздиш. Але під комір залізу.",
            "^snow.під_комір Залізу. Тіко не жени мене звідти.",
            "",
            "@м_руда",
            "^mine.глибина Ше трохи глибше — і в Гель провалимось, {м_слівце}.",
            "^mine.кайло Кайло тупе, як твої жарти, розумнику.",
            "^mine.мідь Мідь, олово, залізо… А мені шось блискуче буде, чи хуй?",
            "^mine.обвал Якшо тут завалить — я перший звалю. А ти — як знаєш.",
            "^mine.жила Жила жирна, {м_слівце}. Аж слина капає.",
            "^mine.піт {name} пріє, як свиня в лазні. Я на плечі вже плаваю, бля.",
            "^mine.камінь Камінь, камінь, камінь. Хоч би один дракон, для різнобою, бля.",
            "^mine.пітьма Тут темно, як у тебе в голові, {м_слівце}.",
            "",
            "@м_руда_кінець",
            "^mine.обережно Гель мене не лякає. Мене лякає, як ти, ботан, трусишся над кожним каменем.",
            "^mine.ниє Я не ною, бля. Я кажу, як є.",
            "^mine.спокій Мій спокій — то коли ти заткнешся.",
            "^mine.заблукаєш Заблукаю — то з тобою. Ти ж полетиш за мною, ботан.",
            "^mine.вкрадеш А я б і зжер, і спиздив. Разом.",
            "^mine.злети Злечу — то в стелю дзьобом вріжусь. Сиджу, плаваю.",
            "^mine.накликай А я накличу. Хоч якесь діло буде.",
            "^mine.світять Світять. Тіко я ніхуя не бачу. Дивно, бля.",
            "^mine.себе Себе я люблю. А тебе — не дуже. Вибір ясний.",
            "^mine.наша Наша — значить і моя. Беру свою частку.",
            "^mine.наша Красти своє — то не крадіжка, то звичка, бля.",
            "^mine.сорока Сорока тягне все. А я тіко блискуче. Різниця.",
            "^mine.чхни Апчхи! Ой. Ну, майже не на тебе.",
            "^mine.дорогий Дорогий? То продай мене. Тіко за багато, бля.",
            "^mine.дорогий Нарешті хтось оцінив. Хай і через пилюку.",
            "^mine.мокрий Мокрий, бо {name} на мене пріє. Не від злості.",
            "^mine.мокрий Злість у мене гаряча, ботан. Сам згориш.",
            "^mine.тихо Тихо, тихо. А як підпалить — я на тобі гаситиму.",
            "^mine.привіт Привіт? Я їй таке передам — сама вилізе.",
            "^mine.привіт Передавай сам. А я тут нагорі почекаю.",
            "^mine.обережно Обережно — то довго. Копай швидше, поки Гель спить.",
            "^mine.смішать Смішать. Тебе самого. Більше нікого.",
            "^mine.смішать Ага. Як кайло — до першого каменя.",
            "^mine.ниє Ною — бо маю право. Я тут найтерплячіший.",
            "^mine.пил_тобі Пил? Дякую, бля. Щедро, як завжди.",
            "^mine.пил_тобі Блискучий пил. Ну… хоч шось. Давай.",
            "^mine.спокій Мій спокій — то блискуче в дзьобі. А не твої лекції.",
            "^mine.сподіваюсь «Сподіваюсь», бля. Ото заспокоїв.",
            "^mine.сподіваюсь Сподівайся. А я вже вихід запам'ятав.",
            "^mine.заблукаєш Я не блукаю. Я розвідую, бля.",
            "^mine.не_їдять А я спробую. Раптом смачна.",
            "^mine.не_їдять Не їдять — бо не пробували. Я буду перший.",
            "^mine.вкрадеш Вкраду — то шматочок. Ніхто й не помітить.",
            "^mine.поважай Поважаю. Носом. Аж очі ріже.",
            "^mine.поважай Чесний, бля. Але смердить нечесно.",
            "^mine.злети Злечу — а ти моє плече займеш. Хуй там.",
            "^mine.накликай Накличу — то ти перший і втечеш, ботан.",
            "^mine.битися Битися хоч весело. А тут камінь.",
            "^mine.битися Так. І шо. Ти б тіко балакав.",
            "^mine.смолоскип Смолоскип бачу. Ідей — ніхуя.",
            "^mine.смолоскип Ідеї в тебе є. Тіко світять, як мокра тріска.",
            "^mine.світять Ага. Як гнилушка на болоті. Тьмяно і смердить.",
            "",
            "@м_риба",
            "^fish.велика Ото рибина! Здоровенна, більша за мене, {м_слівце}!",
            "^fish.черв'як Черв'яка на гачок? Нашо, дай мені, я його сам схаваю.",
            "^fish.зірвалась Зірвалась! Сука, зірвалась! Та шо ж таке!",
            "^fish.смажити Смажити будем чи сиру хавати? Я за сиру, бля.",
            "^fish.поплавець Поплавок смикнувся! Тягни, {м_слівце}, тягни!",
            "^fish.чекати Сидимо, чекаємо. Рибо, ну давай вже, курва.",
            "^fish.кістка Кістка в горлі застрягла, {м_слівце}. Ше з тої риби.",
            "^fish.глибоко А там, у глибині, кажуть, є риба, шо кораблі ковтає. Цілими, бля.",
            "",
            "@м_риба_кінець",
            "^fish.поважай Поважати рибу? Я її зара зжеру, ото й вся повага.",
            "^fish.наживка Я тебе сам наживлю, ботан. На гачок і в воду.",
            "^fish.жити Хоче жити — хай не клює, падла.",
            "^fish.дикуни Самі ви дикуни. Сира — то смак, шариш.",
            "^fish.вітер Сиджу, сиджу. Але смикнулось, я бачив, бля!",
            "^fish.нема_терпіння Є в мене терпіння. Маленьке. Було. Скінчилось.",
            "^fish.жадібно Жадібність — то по життю, ботан. Не вчи.",
            "^fish.воронів Хай спробує. Я їй зсередини печінку видзьобаю, суці.",
            "^fish.хвіст Знов хвіст. Я з тих хвостів уже гніздо можу звити, бля.",
            "~3 ^fish.хвіст Хвіст, ага. Ну хоч жирний дай, жмот пернатий.",
            "^fish.вдавись Не вдавлюсь. Я ж профі, бля.",
            "^fish.вдавись Вдавлюсь — то з кайфом. Давай сюди.",
            "^fish.чесна Чесна, бля. Ти ше скажи — непорочна.",
            "^fish.розлякав Я розлякав? Та я тихо сидів, як миша, бля!",
            "^fish.розлякав Каркотіння — то мій голос. Хай риба звикає.",
            "^fish.терпіння Твоє терпіння мені до сраки. Мені риба треба.",
            "^fish.для_name {name} одну, я одну. Отак чесно, бля.",
            "^fish.мстить Хай мстить. Я її однаково зжеру. З лускою.",
            "^fish.мстить Знає — то хай боїться, {м_слівце}.",
            "^fish.личить Тобі теж личило б. Давай, підставляй око, ботан.",
            "^fish.поважай Поважаю. Зжеру з повагою. Шматок за шматком.",
            "^fish.розумніша Розумніша за мене? То й за тебе, ботан.",
            "^fish.розумніша Розумна, а на гачку. Отакий ваш ум, бля.",
            "^fish.наживка Я — наживка? Та я ту рибу сам зжеру, як підпливе.",
            "^fish.дзьобом Та й ловитиму. Я пірнаю, як баклан, бля.",
            "^fish.дзьобом Дзьобом і зловлю. А ти дивись і заздри.",
            "^fish.жити Як і я? Я ж не клюю на всяку хрінь на гачку.",
            "^fish.кричи Хай чує. Я їй ше й не таке крикну, бля.",
            "^fish.кричи Добре, шепочу. Сука. Зірвалась. Бачиш, тихо.",
            "^fish.дикуни Дикун — то хто смажене жре і пузо гладить. А я гурман, бля.",
            "^fish.щасливі О, оце діло. Перший раз з тобою згоден, бля.",
            "^fish.щасливі Щасливі. Тіко дай мені дві сирих — буду ше щасливіший.",
            "^fish.вітер Вітер у тебе в голові. А поплавок смикнувся.",
            "^fish.сиди Та сиджу. Але як упустить — я скажу, шо казав.",
            "^fish.сиди Сиджу, бля. Тіко хай тягне швидше, бо я сам пірну.",
            "^fish.нема_терпіння Нема. Зате є голод. Він і чекає за мене.",
            "^fish.мовчи Мовчу. Бачиш, як я мовчу? Аж розпирає, бля.",
            "^fish.мовчи Мовчав. Не прийшла. Шо далі, розумнику.",
            "^fish.жадібно Жерти повільно — шоб у мене вкрали? Нє, дякую.",
            "^fish.покарання Покарання, бля. Ти ше скажи, шо риба помолилась.",
            "^fish.покарання Тоді хай карає далі. Я ше одну зжеру.",
            "^fish.кашляни Кха! Пішла. Живий, бля. Не радій.",
            "^fish.кашляни Ото, ботан, і ти на шось годишся.",
            "^fish.перевіряти Ссиш, ботан. А я б глянув. Здалеку.",
            "^fish.перевіряти Ссикун. Хоча… ну її, справді.",
            "^fish.воронів То хай тебе першим. Ти ж розумний — смачніший.",
            "",
            "@м_портал",
            "^portal.світло Те світло в дірці аж сліпить, {м_слівце}.",
            "^portal.шум Після тої дірки у вухах дзвенить. Дзень-дзень, бля.",
            "^portal.рахунок Скіко ми вже разів у ці дірки стрибали, га?",
            "^portal.половина Хугіне, в мене всі лапи на місці? Перелічи, ну.",
            "^portal.звідки А звідки ми, {м_слівце}, щойно вилізли? Забув уже.",
            "^portal.магія Ці каменюки з рунами… Хто їх наліпив? Локі, чи шо?",
            "^portal.мороз Там, між світами, дубак собачий. Як у Ніфльгеймі, бля.",
            "^portal.метал А чого руду крізь дірку не можна тягти? Хто це, бля, придумав?",
            "",
            "@м_портал_кінець",
            "^portal.легший Легший, ага. Тіко тепер у повітрі кручусь, як дурний.",
            "^portal.легший Легший удвічі — і злий удвічі.",
            "^portal.хотів Хоті{в|ла}, бля. А мене хтось питав?",
            "^portal.хотів Ну й добре. Аби не в морі, бо там я блюю.",
            "^portal.вдома Знайомо? Твоєю мудрістю пахне. Значить, біда.",
            "^portal.вдома Вдома — то де жратва. Зараз перевірю.",
            "^portal.болото Через болото хоч видно, куди йдеш.",
            "^portal.болото Болото, бля. Ото ти вмієш втішити.",
            "^portal.локі Хай слухає. Я тому Локі все одно не вірю.",
            "^portal.локі Слухає? То хай і чує: Локі — падло.",
            "^portal.заплющ Заплющив. І в тебе врізався. Дякую, порадник хуїв.",
            "^portal.заплющ Не хочу, бо бачу тебе.",
            "^portal.шлях Шлях між світами — а лампу нормальну не повісили.",
            "^portal.шлях Розумний ти. А сліпить однаково.",
            "^portal.совість Совість? Не, в мене такої нема. То дзвін.",
            "^portal.совість Совість, бля. Хай спершу твоя заговорить.",
            "^portal.минеться Минеться, минеться… А поки дзвенить, курва.",
            "^portal.минеться Всі на місці. Тіко вуха десь лишились.",
            "^portal.рахую Рахує він, бля. Краще б жратву рахував.",
            "^portal.рахую Рахуй. А мені й так погано.",
            "^portal.лаявся Майже, бо я лаюсь більше. Факт.",
            "^portal.лаявся Тоді дофіга. Бо я лаюсь, як дихаю.",
            "^portal.дві Дві? А відчуваю три. Шо за хуйня.",
            "^portal.дві Дві. Ну й добре. Бо ти тіко до двох рахувати й вмієш.",
            "^portal.розум Розум — то твоє. Мені лап досить.",
            "^portal.розум Розум мені нашо? Я на тобі їжджу.",
            "^portal.дім Дім пам'ятаю. Дім — то де жратва.",
            "^portal.дім З дому? То нашо ми звідти вилізли?",
            "^portal.бурчав Я завжди бурчу. То не прикмета, то характер.",
            "^portal.бурчав Бурчав — значить, звідусіль.",
            "^portal.майстри Давні майстри… Хай їм гикнеться, падлам.",
            "^portal.майстри Майстри, бля. Не могли зробити, шоб не нудило.",
            "^portal.зламаються Зламаються — коли ми всередині. Як завжди.",
            "^portal.зламаються Дякую, ботан. Тепер я боюсь стрибати.",
            "^portal.нічого Мене нема — то й холодно. Логіка.",
            "^portal.нічого Нема мене — то й тепла нема. Сам сказав.",
            "^portal.затримуємось Холодно, курва. Ненавиджу ту дірку.",
            "^portal.затримуємось Не затримуємось, ага. А дзьоб однаково примерз.",
            "^portal.лайка А я не люблю тебе. І шо?",
            "^portal.лайка Любить, не любить — а нам руду пішки пертись.",
            "^portal.боги Боги — жмоти. Як і ти.",
            "^portal.боги Боги вирішили — хай боги й тягнуть.",
            "",
            "@м_вага",
            "^heavy.спина Спина під нами тріщить, {м_слівце}. Я ж чую.",
            "^heavy.жадібність Все тягнем. Навіть сміття всяке.",
            "^heavy.легкий Хочеш, я злечу — і легше стане? Ні? Ну то й сиджу.",
            "^heavy.віз Чого ми візок не взяли? Ну чого, га?",
            "^heavy.повільно Повземо, а день, бля, минає.",
            "^heavy.скриня Премо, наче скриню з золотом. А там — дошки, бляха.",
            "^heavy.кульгає Ми шкандибаємо, {м_слівце}. Ше трохи — і гепнемось разом.",
            "^heavy.відпочинок Перекури, {м_слівце}. Ну хоч хвилинку.",
            "",
            "@м_вага_кінець",
            "^heavy.повземо Ну, повземо. Як завжди, хай йому грець.",
            "^heavy.повземо То я злітаю. А ти пішки повзи.",
            "^heavy.мовчать Мовчу. Повзу. Ненавиджу. Всіх.",
            "^heavy.мовчать То я не черепаха. Я вагітний ворон, і мені погано.",
            "^heavy.доповзе Я б долетів, ботан. Це {name} повзе.",
            "^heavy.доповзе Доповзе, ага. До зими.",
            "^heavy.майбутнє Майбутнє, бля, важке. Як твої жарти.",
            "^heavy.майбутнє Важке в нас майбутнє. І незручне.",
            "^heavy.тебе Мене кинути? Та без мене {name} пропаде.",
            "^heavy.тебе О, то я теж у торбі? Тоді ясно, чого важко.",
            "^heavy.бурчання Тріщить, гарчить — яка, бля, різниця. Важко!",
            "^heavy.бурчання Бурчання не тріщить, ботан. Тріщать кістки.",
            "^heavy.дійдемо Дійдемо, ага. Як ноги не відваляться.",
            "^heavy.дійдемо Відпочинемо. Якшо хтось доживе.",
            "^heavy.знадобиться Ага, знадобиться. Коли ми під ним здохнемо.",
            "^heavy.знадобиться Мені зараз знадобився б перекур. А не сміття.",
            "^heavy.скупий То ми тричі носимо. Бо ше й дурні.",
            "^heavy.скупий Скупий двічі, а ми — щодня.",
            "^heavy.пірїнка Пір'їнку? Я важу, як ковадло. Від злості.",
            "^heavy.пірїнка Пір'їнка, бля. Я цілий ворон.",
            "^heavy.злітай З камінням? То я тобі одне на голову принесу.",
            "^heavy.злітай Злетів би. Але лінь. Сиджу.",
            "^heavy.донесе Донесе, ага. На карачках.",
            "^heavy.донесе Думати — то не {його|її} сильна сторона.",
            "^heavy.пригоди Пригоди з грижею. Ото кайф, курва.",
            "^heavy.пригоди То хай розумні й тягнуть.",
            "^heavy.насмішиш Та з нас і так ржуть. Повільно.",
            "^heavy.насмішиш Смішити нікого. Тут тіко ми й комарі.",
            "^heavy.безпечно Ніхто не женеться, бо всі зі сміху здохли.",
            "^heavy.безпечно Повземо, як слимаки. Героїчні слимаки, йо.",
            "^heavy.хата Хата з дошок. А я хотів золоту, як в Одіна.",
            "^heavy.хата Золото, ага. Тіко спина від нього не золота.",
            "^heavy.чесніші Чесніші, бо нікому не треба.",
            "^heavy.чесніші Чесні дошки — то ти, ботан. Плоский і важкий.",
            "^heavy.тримайся Тримаюсь. Кігтями. За {name}.",
            "^heavy.тримайся Тримаюсь, ага. За останнє пір'я.",
            "^heavy.падати Гепатись — то в нас спільне, ага.",
            "^heavy.падати По моїй. Тому я й знаю — гепнемось.",
            "^heavy.хвилинка Хвилинка — то мало. Давай дві.",
            "^heavy.хвилинка Хоч так. Сідаю. Нє, я ж і так сиджу.",
            "^heavy.балачки Я твою мудрість на собі тягну, ботан. Важче за камінь, бля.",
            "^heavy.балачки Від балачок я не втомлююсь. То мій відпочинок.",
            "",
            "@м_відбивається",
            "^gap_h.лайка>gap_h.нудний Не матюкаєшся — бо нудний, як пень, {м_слівце}.",
            "^gap_h.довіра>gap_h.плює Довіра — то нашийник. Носи сам, песик.",
            "^gap_h.слухає>gap_h.бубниш Слухає тебе? Бо ти бубниш, і під тебе добре спиться.",
            "^gap_h.наздоганяй>gap_h.наздожену Наздожену й переплюну. Прям плюну, ага.",
            "~1 ^gap_h.довіра|gap_h.слухає|gap_h.наздоганяй|gap_h.лайка>gap_h.погроза Ше слово, ботан, — і пір'я в тебе поменшає. Сильно.",
            "~3 ^gap_h.довіра|gap_h.слухає|gap_h.наздоганяй|gap_h.лайка>gap_h.молодець Ну… красень. Тіко я все одно крутіший, {м_слівце}.",
            "^gap_h.слухає>gap_h.протягне Та {name} без мене й дня не протягне, {м_слівце}.",
            "^gap_h.наздоганяй>gap_h.наздожену Не бзди, наздожену. І тоді ти в мене поплачеш.",
            "^gap_h.лайка>gap_h.чесність Лайка — то чесність, ботан. А ти — гладенький брехунець.",
            "",
            "@м_хвалиться",
            "^gap_m.чесний Мене {name} більше любить, вкурив? Бо я чесний гівнюк.",
            "^gap_m.любить Бачив, як {name} мені лиситься? А тобі — хуй.",
            "^gap_m.росте Довіра в мене — як кігті. Гостра й росте. А в тебе шо?",
            "^gap_m.позаду Наздоганяй, ботан. Хоча куди тобі, з твоїми розумностями.",
            "^gap_m.позаду Ше трохи — і я тут улюбленець. А ти — так, пір'я на вітрі.",
            "~1 ^gap_m.позаду Ти позаду, як завжди, лошара. Звикай.",
            "~3 ^gap_m.позаду Я попереду, Хугіне. Але й ти нічо. Майже. Трошки.",
            "^gap_m.годує Мене першим годують. Оце, бля, і є довіра, шариш?",
            "",
            "@м_ревнощі",
            "^fed_hugin.мені Ага, Хугіну знов {food}. А я шо, для краси тут сиджу?",
            "^fed_hugin.любимчик Бачу, хто тут улюбленчик. Я все запам'ятаю, {м_слівце}. Все.",
            "^fed_hugin.вдавися Хугін жере, а я дивлюсь, як пес під столом. Шоб ти вдавився, сука.",
            "^fed_hugin.вдавися Смачно тобі, ботан? Шоб ти вдавився.",
            "^fed_hugin.мені {food}… Мені б теж. Та кому я, нахуй, потрібен.",
            "~1 ^fed_hugin.любимчик Його годувати — шо сову годувати. Чим він кращий, га?",
            "~3 ^fed_hugin.мені Ну добре, хай пожере. А мені шо, ні крихти?",
            "^fed_hugin.любимчик {name}, в тебе два ворони, алло! Чи вже тіко один улюбленчик?",
            "^fed_hugin.вдавися Жери, жери. Шоб тобі поперек горла стало, {м_слівце}.",
            "",
            "@м_погроза",
            "^fed_hugin.крихта Крихту він дасть. А я тобі — дулю. Чекай.",
            "~1 ^fed_hugin.крихта Засунь ту крихту собі під хвіст.",
            "~23 ^fed_hugin.крихта Давай вже дві, раз такий щедрий.",
            "~3 ^fed_hugin.попрошу Ловлю на слові, засранцю.",
            "^fed_hugin.попрошу Ага, попросить він. Я сам візьму.",
            "~1 ^fed_hugin.попрошу Обіцянки-цяцянки. Я це запам'ятаю, {м_слівце}.",
            "^fed_hugin.попрошу Я тобі те «попрошу» ше пригадаю.",
            "^fed_hugin.проси Попрошу, {м_слівце}. Так, шо весь Мідгард оглухне.",
            "^fed_hugin.проси Я не проситиму. Я візьму. Твоє.",
            "^fed_hugin.мовчи Заздрю, і шо? Шоб ти вдавився, {м_слівце}.",
            "^fed_hugin.мовчи Не замовкну. Я все запам'ятовую. Все.",
            "~3 ^fed_hugin.мовчи Ладно, мовчу. Але наступний шматок — мій, засранцю.",
            "^fed_hugin.дражнить Жери-жери. Я почекаю, поки заснеш. Гиги.",
            "^fed_hugin.дражнить Вночі прийду і очі тобі виклюю. Обидва.",
            "^fed_hugin.дражнить Ну-ну. Колись і я буду ситий, а ти — ні. Чекай.",
            "~3 ^fed_hugin.дражнить Смакуй, смакуй. Але наступний шматок — мій. Домовились.",
            "",
            "@м_ситий",
            "~1 ^fed_munin.заслуги>fed_munin.заслуга Сталося те, шо ти, ботан, тепер другий. Звикай.",
            "~3 ^fed_munin.заслуги>fed_munin.заслуга Заслужив, бо гарний. Не те шо деякі.",
            "^fed_munin.чавкає>fed_munin.чавк Чавкаю, бо смачно. А ти слухай і рюмсай.",
            "^fed_munin.чавкає>fed_munin.чавк Манери на голодний шлунок не жеруть, ботан.",
            "~1 ^fed_munin.чавкає>fed_munin.чавк Не подобається — затули вуха крилом.",
            "^fed_munin.подобрієш>fed_munin.злий Подобрішаю? Не діждешся, {м_слівце}.",
            "^fed_munin.подобрієш>fed_munin.злий Від жратви я тіко злішаю. Отак.",
            "^fed_munin.заздрю>fed_munin.дуля А ти заздри, заздри, {м_слівце}. Тобі корисно.",
            "^fed_munin.заздрю>fed_munin.дуля Дивись, дивись. Очима не нажерешся, ботан.",
            "~1 ^fed_munin.заздрю>fed_munin.зжеру Ше раз зирнеш — і тебе зжеру. На закусь.",
            "^fed_munin.радий>fed_munin.дуля Радий він. Слиною вже весь дзьоб закапав.",
            "^fed_munin.радий>fed_munin.дуля Щирий? Тоді дивись, як я доїдаю.",
            "",
            "@м_кінець",
            "^gap_m.наздожену Ага. Я ше дальше буду, поки ти наздоганяєш.",
            "~3 ^gap_m.наздожену Наздоганяй. Тіко не відставай сильно, бо нудно.",
            "^near_death.зілля_логіка Логіка, {м_слівце}, ага. Наступного разу сам носи, розумний.",
            "^near_death.зілля_логіка Логіка в тебе є, а зілля нема. Чудово.",
            "^near_death.зілля_крила Крила в нього. Хоч би раз ними шось корисне приніс.",
            "^near_death.зілля_крила То на крилах і принось наступного разу. Носильник.",
            "^near_death.гордість_гордість Гордості в мене нема. Тіко злість. А злість не вбиває.",
            "^near_death.гордість_гордість Ой, філософ. Я жити хочу, а не гордитись.",
            "^near_death.гордість_вміє Вміє, ага. Аж я з плеча мало не злетів.",
            "^near_death.гордість_вміє Вміє. Я {його|її} й навчив, шоб ти знав.",
            "",
            "@м_рубка",
            "^chop.білка>chop.вбивці Ну так ми й є вбивці. Дерев, {м_слівце}.",
            "^chop.білка>chop.зжеру Хай чеше. Наступного разу зжеру, руду.",
            "^chop.смола>chop.злість А я злістю смерджу. Натурально, бля.",
            "^chop.смола>chop.рюмсає Смола — то дерево рюмсає. Хай рюмсає, нюня.",
            "^chop.пеньок>chop.ямка Який там пеньок. Від мого терпіння вже ямка лишилась.",
            "^chop.пеньок>chop.пеньок_діло Пеньок — теж діло. Сісти можна. Насрати можна.",
            "^chop.гнізда>chop.сміливіше Чужі? То рубай, нахуй, сміливіше.",
            "^chop.гнізда>chop.яйця Шкода, яйця не схавали. Сніданок пропав.",
            "^chop.стук>chop.понти Яке серце, бля? Ліс — то дрова з понтами.",
            "^chop.стук>chop.башка Тук-тук. Як у мене в башці від тебе.",
            "^chop.старе>chop.трухляве Старе — значить трухляве. Як твої жарти, ботан.",
            "^chop.старе>chop.колода Було. Тепер — колода. Всі ми колись колоди, йо.",
            "^chop.кора>chop.жуки Кора смачна. Для жуків. Не для мене, нє.",
            "^chop.кора>chop.шо_вийде Корабель з неї буде. Чи хата. Чи дрова, курва. Шо вийде.",
            "^chop.луна>chop.хай_приходять Хай знають. Хай приходять, я їм дам.",
            "^chop.луна>chop.бояться Та ніхто не припреться. Всі мене бояться. Всі!",
            "",
            "@м_друг",
            "^friend.спомин>friend.спомин_нічо Пам'ятаю. Нічо доброго, бля.",
            "^friend.спомин>friend.спомин_пірʼїна Пам'ятаю. Я тоді пір'їну проїбав. Хорошу пір'їну.",
            "^friend.частування>friend.частування_раз Чемним? За жратву — буду. Раз. Цього разу.",
            "^friend.частування>friend.частування_ситих Чемність — то для ситих, ботан.",
            "^friend.броня>friend.броня_дзьобнути Блищить? Дай дзьобнути. Хоч разок.",
            "^friend.броня>friend.броня_вній Броня гарна. А от те, шо в ній, — так собі.",
            "^friend.гомін>friend.гомін_перекричу А я їх перекричу. Одним матюком.",
            "^friend.гомін>friend.гомін_горлають Хай горлають. Хоч не нудно, бля.",
            "^friend.допомога>friend.допомога_хоче Допомагає, бо шось хоче, {м_слівце}. Сто пудів.",
            "^friend.допомога>friend.допомога_незаважатиму Ну хай допомагає. Я не заважатиму. Сильно.",
            "^friend.смажене>friend.смажене_непринесли Смаженим? То чого нам нічо не принесли, га?",
            "^friend.смажене>friend.смажене_слина Я вже слиною капаю, {м_слівце}.",
            "^friend.спина>friend.спина_ніж Прикрита? Аби ножем не прикрили.",
            "^friend.спина>friend.спина_дзьобом Спину я сам прикрию. Дзьобом, бля.",
            "^friend.розмова>friend.розмова_люди Розумне? Від людей? Ой, не смішіть мене.",
            "^friend.розмова>friend.розмова_хуйня Я слухаю. Поки шо — хуйня якась.",
            "",
            "@м_падіння",
            "^fall.кущ Гепнулись у кущ. У колючий, {м_слівце}. Ой-ой.",
            "^fall.багно Плюхнулись у багно. Тепер ми однієї масті.",
            "^fall.політ Секунду ми летіли. Найкраща секунда за день, бля.",
            "^fall.каміння Каміння поруч летіло. Я рахував, {м_слівце}, чесно.",
            "^fall.висота Звідки ми гепнулись? З неба, чи шо?",
            "^fall.синці Синці будуть, {м_слівце}. Не в мене, і то добре.",
            "^fall.сміх Гиги! Я досі ржу, {м_слівце}. Це було шикарно.",
            "^fall.вдруге Це вже вдруге за день, {м_слівце}. Вдруге!",
            "",
            "@м_падіння_кінець",
            "^fall.підказуй Та {він|вона} мене й так не слухає.",
            "^fall.підказуй Пізно. Вже, дивись, на ту скелю зирить.",
            "^fall.передумає Дивись, дивись. А я вже не можу на це дивитись.",
            "^fall.передумає Подивись. Тіко {він|вона} в тебе не дивиться.",
            "^fall.земля Ворушиться ж. Значить, факт.",
            "^fall.земля {name} теж витрима{в|ла}. Наче.",
            "^fall.швидко Швидко — не значить правильно, професоре. Навіть я шарю.",
            "^fall.швидко Швидко, ага. Наступного разу — ше швидше, одразу в могилу.",
            "^fall.поспішає Поспіх — то для бліх. А {name} в нас, виходить, блоха.",
            "^fall.поспішає Поспішає, бля. Куди — в землю?",
            "^fall.лінь Лінь — то святе. Але ж не так, бляха.",
            "^fall.лінь Знайомо. Але я хоч з крилами лінуюсь.",
            "^fall.мякий М'який? Я тепер, бля, як їжак.",
            "^fall.мякий Майже — то ключове слово, ботан.",
            "^fall.подякуй Дякую, кущику. Бля, я шо, з кущем розмовляю?",
            "^fall.подякуй Подякую. Коли колючки з сраки витягну.",
            "^fall.чорний Чорний — то стиль, ботан. А багно — то зашквар.",
            "^fall.чорний Чорний, але чистий. Був.",
            "^fall.помиємось Колись — то ніколи. Я тебе знаю.",
            "^fall.помиємось Ти помиєшся. А я так і ходитиму, як свиня.",
            "^fall.приземлення Похуй. Все одно найкраща секунда.",
            "^fall.приземлення Приземлення — то вже не моя секунда.",
            "^fall.чужі Чужі — найсмачніші, ага.",
            "^fall.чужі Люблю. Свої болять, а чужі смішать.",
            "^fall.скільки Три. І всі повз. Я ж казав — фартові ми.",
            "^fall.скільки Сім. Нє, вісім. Збився, бо гепнулись.",
            "^fall.голова На голову — то було б смішно. Але не мені.",
            "^fall.голова Одне по хвосту чиркнуло. Я не скаржусь. Майже.",
            "^fall.ідея Дурні ідеї — мої найулюбленіші, ага.",
            "^fall.ідея Висока, бля. Аж дух забило.",
            "^fall.стежка Стежки нема — то й не лізь. Навіть я шарю.",
            "^fall.стежка Тепер є. Ми її протоптали. Сракою.",
            "^fall.медалі То ми герої. Синюваті, бля.",
            "^fall.медалі Медалі, ага. {name} ними вже весь обвішаний.",
            "^fall.переломи Переломи — то наступного разу. Я сракою чую.",
            "^fall.переломи Не переломи, ага. Поки що.",
            "^fall.некрасиво Некрасиво, зате від душі.",
            "^fall.некрасиво Красиво — то не про нас, ботан.",
            "^fall.смішно Трохи? Я ледь з плеча не впав.",
            "^fall.смішно От бачиш. Навіть ти ржеш, ботан.",
            "^fall.третього Буде й третій. Я сракою чую.",
            "^fall.третього Пильнуй. Тіко {він|вона} тебе не слухає.",
            "^fall.рідна Рідна, бля. Скоро й ночувати на ній будемо.",
            "^fall.рідна Ше трохи — і земля з нами вітатиметься.",
            "",
            "@м_данж",
            "^dungeon.павуки>dungeon.жеру Павуки мене бояться. Бо я їх жеру.",
            "^dungeon.павуки>dungeon.пошкодує Заплутаюсь — то павук пошкодує, шо вилупився.",
            "^dungeon.капає>dungeon.черга Мене все бісить. Вода — в черзі, після тебе.",
            "^dungeon.капає>dungeon.поради Кап-кап. Як твої поради, ботан. Нудно й мокро.",
            "^dungeon.двері>dungeon.ламай Значить, там шось цікаве. Ламай.",
            "^dungeon.двері>dungeon.страшне Замкнули, бо там шось страшне. Пішли, бля!",
            "^dungeon.шепіт>dungeon.плітки То драуґри пліткують. Про тебе, ботан.",
            "^dungeon.шепіт>dungeon.нечую Я ніхріна не чую. Бо я не ссикло.",
            "^dungeon.пастка>dungeon.перший Пастки — для дурнів. От ти й іди перший.",
            "^dungeon.пастка>dungeon.над Я над підлогою, бля. Мені байдуже.",
            "^dungeon.задуха>dungeon.затхлятина Затхлятина — мій улюблений запах. Трупиками тхне, ммм.",
            "^dungeon.задуха>dungeon.дихай Дихай менше. І пизди менше.",
            "^dungeon.вихід>dungeon.ліво Та пам'ятаю я. Ліво, право, ше раз ліво. Ніби.",
            "^dungeon.вихід>dungeon.житимем Загубимось — то й житимем тут. Бабла тут повно.",
            "^dungeon.череп>dungeon.почув Бо здох до того, як тебе почув. Пощастило мужику.",
            "^dungeon.череп>dungeon.знає Лиситься, бо знає шось, чого ми не знаємо. Падло.",
            "",
            "@м_перехід_відповідь",
            "^cross_h.звірина>cross_h.звірина_куштував Інша? То й шо. Нова — значить, я її ше не куштував.",
            "^cross_h.звірина>cross_h.звірина_здорові Сліди здорові, бля. Оце я розумію — є кого гасити.",
            "^cross_h.барви>cross_h.барви_сіре Барви-шмарви. Сіре, зелене, гівняне — от і всі барви.",
            "^cross_h.барви>cross_h.барви_ляпнеш Ну… гарно, шо. Ляпнеш комусь, шо я так сказав, — око виклюю.",
            "^cross_h.подих>cross_h.подих_звідки Я дму, звідки хочу, {м_слівце}. І шо ти мені зробиш?",
            "^cross_h.подих>cross_h.подих_кент Вітер — то мій кент. Такий самий злий і без мізків.",
            "^cross_h.бували>cross_h.бували_зжерли Ага, пам'ятаю. Тут нас мало не зжерли, курва. Класно було.",
            "^cross_h.бували>cross_h.бували_непригадую Бували. Шось нічо хорошого не пригадую. Та й похуй.",
            "^cross_h.від>cross_h.від_мухи Спокійніше? Та там мухи дохли від нудьги, братан.",
            "^cross_h.від>cross_h.від_завалимо Побачимо, ага. І когось завалимо. Сто пудів.",
            "^cross_h.карта>cross_h.карта_носом Та запам'ятав. Межа — де смердить по-іншому. Шариш?",
            "^cross_h.карта>cross_h.карта_нажерся Вертатися? Нашо? Я ше не нажерся.",
            "^cross_h.пташки>cross_h.пташки_дізнаються Співають, бо не знають, шо я поруч. Зара дізнаються.",
            "^cross_h.пташки>cross_h.пташки_пузо Шо там птахи… Я чую тіко, як у мене пузо бурчить.",
            "^cross_h.нове>cross_h.нове_весело Небезпечне? Йо, то ж весело! Пішли вже, не сци.",
            "^cross_h.нове>cross_h.нове_ззаду Ну то ти й лізь спереду, професоре. А я прикрию. Ззаду. Здалеку.",
            "",
            "@м_перехід",
            "^cross_m.нюх Нюх-нюх… О, нові смаки, {м_слівце}. Шось тут їстівне по-любому.",
            "^cross_m.стовп Ні стовпа, ні знака, бля. Хто так межі ставить, га? Руки б повідривав.",
            "^cross_m.тут Все, {biome_here}. Ну, хто тут найзліший? Крім мене, ясно.",
            "^cross_m.назад {from_in} хоч гівно було знайоме, рідне. Пішли назад, а?",
            "^cross_m.погода Погода тут якась не така. Гірша, курва мать.",
            "^cross_m.слід Йо, хтось тут ходив. Слід здоровенний. Хочу глянути, чий. Зблизька.",
            "^cross_m.дерева Дерева тут криві, як твої поради, ботан.",
            "^cross_m.край Ідемо, ідемо, ідемо… Де той край? Я вже заїбався.",
            "",
            "",
            // the talks between the ravens: new threads for fog, night, boss, death, a new land and the fireside
            "@м_туман",
            "^fog.звуки>fog.живіт То в мене в пузі. Я голодний, а ти — кроки, кроки.",
            "^fog.звуки>fog.бійка Кроки. Здоровенні. Ну все, {м_слівце}, зара буде бійка.",
            "^fog.дорога>fog.троль На дорозі, де ж ше. Он камінь, он кущ. Чи то троль. Хуй його знає.",
            "^fog.дорога>fog.болото Дорога — там, куди {name} пре. Хоч у болото.",
            "^fog.мряка>fog.драуґр Та краще б драуґр, {м_слівце}. Йому хоч у пику дати можна. А туман шо?",
            "^fog.мряка>fog.притулися Холодно, бля. Ну… притулися, чи шо. Тіко без телячих ніжностей.",
            "^fog.силует>fog.троль_сто Троль, сто пудів, {м_слівце}. Я печінкою чую. Готуй дзьоба.",
            "^fog.силует>fog.дерево Та дерево. Але я б дзьобнув. Хай знає.",
            "^fog.голос>fog.матюком Та я вже відповів. Матюком. Трьохповерховим.",
            "^fog.голос>fog.гукну Кличе? То я йому зара так гукну, {м_слівце}, шо сам прибіжить.",
            "^fog.тримайся>fog.пазуха Я й так на плечі, ало. Ближче — тіко в пазуху.",
            "^fog.тримайся>fog.запах Розгубимось — знайду тебе по запаху. Ти смердиш книжками, ботан.",
            "^fog.вогник>fog.пішли Ну бачу. Пішли туди, хай там хоч дідько з рогами сидить.",
            "^fog.вогник>fog.болотний То болотний вогник, {м_слівце}. Дурнів заманює. Тебе, наприклад. Гиги.",
            "^fog.тиша>fog.курва Нічо не глушить. Слухай сюди: КУРВА.",
            "^fog.тиша>fog.не_подобається Глушить, бляха. Мені це не подобається, чуєш?",
            "^fog.мокро>fog.злість Я важкий не від туману. Я від злості важкий.",
            "^fog.мокро>fog.пси Обтрусимось. Як пси. Шо тут думати.",
            "",
            "@м_ніч",
            "^night.зорі Зорі повилазили, {м_слівце}. Як блохи на собаці. Аж небо чухається.",
            "^night.сова Сова верещить. От би їй голову відкрутити, падлюці.",
            "^night.місяць Шо вирячився, місяцю? Га? Тебе питаю, пико лиса.",
            "^night.холод Холодно вночі, {м_слівце}. Лапи задубіли нахуй.",
            "^night.шурхіт Шось шурхотить у траві. Дзьобнути, чи шо?",
            "^night.сон Хугін, ти спиш? Не спи, бо мені нудно, курва.",
            "^night.драуґри Вночі драуґри вилазять. Хочу одному в гниле око дзьобом. Хрясь!",
            "",
            "@м_кінець",
            "^rest_b.не_каркай Я не каркаю. Я ворон, я так розмовляю.",
            "^rest_b.не_каркай Хай буде. Але я одним оком пасу.",
            "^rest_b.мовчиш То я не мовчатиму. Шоб тобі спокійно було.",
            "^rest_b.мовчиш Ну то радій, ботан. Я ше довго не замовкну.",
            "^rest_b.краще Краще? Ти співаєш, як колесо скрипить.",
            "^rest_b.краще Тіко не співай, {м_слівце}. Благаю. Я ж ворон, а не камінь.",
            "^rest_b.хотілося От і не хоти. Вуха ціліші будуть.",
            "^rest_b.хотілося Хотілося йому… Перехочеться, {м_слівце}.",
            "^rest_b.не_сміюсь Ну от. Тіко нікому, ясно?",
            "^rest_b.не_сміюсь Не смієшся? Підозріло. Але хай.",
            "^rest_b.посидимо Посидимо. Тіко ти мовчи, а то зіпсуєш.",
            "^rest_b.посидимо Давай. Я нікуди й не збирався, {м_слівце}.",
            "^gap_m.тиха Тихих любить? Тихих забувають, ботан.",
            "^gap_m.тиха Тиха, бо її нема. Нема — то й тихо.",
            "^gap_m.радий Радий? То не бреши, а заздри нормально.",
            "^gap_m.радий Чесно? Ти? Ну, запишу в пам'ять.",
            "~3 ^gap_m.радий Та ну тебе. Аж незручно, бля.",
            "^gap_m.випрошую Не верещу і не випрошую — вимагаю. Різниця, ботан.",
            "^gap_m.випрошую Талант, бля. Тобі не дано.",
            "^gap_m.пиріг Все можна з'їсти першим. Дивись і вчись.",
            "^gap_m.пиріг Не пиріг? Шкода. Я б її вже зжер.",
            "^gap_m.голосніший Голосніший і попереду. А ти розумний і ззаду.",
            "^gap_m.голосніший Розумний, а позаду. Ото й уся твоя мудрість.",
            "^gap_m.хам Хам, зате улюблений. Ковтни, ботан.",
            "^gap_m.хам Хам — то не лайка, то стиль.",
            "^gap_m.сир То був не сир, то була компенсація.",
            "^gap_m.сир Сир сам упав. Я тіко підхопив.",
            "^gap_m.пузо Пузо — то запас, ботан. На чорний день.",
            "^gap_m.пузо Пузо теж м'яз. Найголовніший.",
            "^gap_m.запах Від мого запаху вовки тікають. То плюс.",
            "^gap_m.запах Запах — то характер, ботан. Нюхай і заздри.",
            "^rest_b.дракон Пиздиш, як Локі. Навіть гірше.",
            "^rest_b.дракон Не вірю. Дракон би тебе одним чихом засмажив.",
            "^rest_b.від_тебе Не пам'ятаю. Але пишаюсь, {м_слівце}.",
            "^rest_b.від_тебе Спросоння? То я ше ласкаво клюнув.",
            "^rest_b.заснеш Ну ти й жлоб. Ріг меду пожалів.",
            "^rest_b.заснеш Засну, то й шо? Хвіст у тебе м'який.",
            "^rest_b.вода Вода? Я шо тобі, жаба?",
            "^rest_b.вода Заслужив я більше за тебе. Я хоч б'юсь, {м_слівце}.",
            "^rest_b.гарний Найгарнішого? А, ну тоді ясно. На мене, кого ж ше.",
            "^rest_b.гарний Ото ж бо. Тебе він десятою дорогою обходить.",
            "^rest_b.пересядь Не пересяду. Це моє місце, хай дим пересідає.",
            "^rest_b.пересядь Теж не любить? То нас двоє, {м_слівце}. Ми з димом заодно.",
            "^rest_b.про_тебе Ха-ха. Смішно. Я аж не засміявся, бачиш?",
            "^rest_b.про_тебе Про мене — то тіко хороше, ясно? Або нічо.",
            "^rest_b.мовчав Ворон, шо мовчав? Таких не буває. Вигадка й є.",
            "^rest_b.мовчав Нудно вже з першого слова. Давай про бійку, {м_слівце}.",
            "^rest_b.відсунься Ну відсунувся. Але вогонь я запам'ятав. Він ше своє отримає.",
            "^rest_b.відсунься Один, ага. І той тепер смердить паленим.",
            "^rest_b.не_любить Взаємно. Я в нього зара плюну.",
            "^rest_b.не_любить Я не ображаюсь. Я мщу, {м_слівце}.",
            "^rest_b.відпочивають Відпочивають. Ссикуни відпочивають.",
            "^rest_b.відпочивають Тоді відійдем від вогню. На два кроки.",
            "^rest_b.уві_сні Уві сні — то не те, шо наживо. Ну добре, хай буде.",
            "^rest_b.уві_сні Уві сні я тебе першого приб'ю, ботан.",
            "^rest_b.чемно Чемно? Я? Ну… спробую. Дай шматок. Будь ласка.",
            "^rest_b.чемно Чемно я не вмію. Я вмію швидко.",
            "^rest_b.поділиться Як завжди — то кісткою. А я хочу м'ясо.",
            "^rest_b.поділиться Поділиться, бо я дивитимусь отак. Жалібно.",
            "^rest_b.пощастило Пощастило, ага. Тіко не звикай, бо наврочиш.",
            "^rest_b.пощастило Не нам пощастило. То {name} з нами пощастило.",
            "^rest_b.чужі Холодний ти, як риб'яче пузо.",
            "^rest_b.чужі Ну й гівнюк ти. Я ж так, спитав.",
            "^night.думки Думай. А я поки кігті розімну.",
            "^night.думки Думки — то для тих, кому нема кого бить.",
            "^night.темрява Я в темряві бачу краще за тебе, сліпий.",
            "^night.темрява Ну хоч зранку комусь напихаю.",
            "^night.голова Є, ага. Пуста, як барило після свята.",
            "^night.голова А в мене не голова, а кулак. З дзьобом.",
            "^night.задумав Задумав. Але не скажу, {м_слівце}. Сюрприз.",
            "^night.задумав Нічо я не задумав. Поки шо.",
            "^night.вовк Не нашого. {name} ше тут, я лапами чую.",
            "^night.вовк Вовк? То в нього можна відібрать. Я б спробував.",
            "^night.сухар Сухарем? І мовчить, жмот.",
            "^night.сухар Сухар — теж їжа. Хай ділиться, {м_слівце}.",
            "^night.хворий Хворий — то ти. А я голодний.",
            "^night.хворий Хворий, зате ситим буду. А ти — ні.",
            "^night.тонкий Тонкий, зате розумний. От тебе першим і зжеруть.",
            "^night.тонкий То за {name} сховаюсь. Там є за чим.",
            "^night.розкажу Розказуй. Хто тобі повірить, ботан?",
            "^night.розкажу Розкажеш — я тобі пір'я в хвості перелічу.",
            "^night.ліс Ліс говорить, а ти перекладаєш. Мовчи вже.",
            "^night.ліс Ага. Слухай ліс. Не мене, а ліс, {м_слівце}.",
            "^night.як_ти Я не тихий, коли сплю. Я хроплю. Сам казав.",
            "^night.як_ти Ти дивишся, як я сплю? Дивак, бля.",
            "^night.скиглиш Я теж голодний. І я ближче. Тож слухай мене.",
            "^night.скиглиш Скиглю, бо ти не годуєш. Вовків хоч зграя годує.",
            "^night.не_підходили Підійдуть — я їм заспіваю, {м_слівце}. Втечуть.",
            "^night.не_підходили Хай підходять. Я їм носи пообдзьобую.",
            "^night.здивований Здивований чим? Моєю красою, сто пудів.",
            "^night.здивований Двоє — то двоє. Я двох подужаю. Мабуть.",
            "^night.курча Курчам? Йди сам глянь, розумнику. Я тут посиджу.",
            "^night.курча Світлячки так не моргають, {м_слівце}. Я бачив.",
            "^night.романтик Та блохи, зорі — одна хуйня. Дрібне все.",
            "^night.романтик Романтик, ага. Я ше й вірші про блох знаю.",
            "^night.уважніше Подивився. Чухаються.",
            "^night.уважніше Уважно дивитись — то твоя робота. Моя — дзьобать.",
            "^night.сторож Сторож… А верещить, як різана.",
            "^night.сторож Сторож тут я. Хай сова мовчить.",
            "^night.мудра Мудра, бо ти так сказав? Ти й себе мудрим кличеш.",
            "^night.мудра Мудрих я не люблю. Тебе ж якось терплю.",
            "^night.заблукав Хай світить. Тіко не на мене, бо дзьобну.",
            "^night.заблукав Я й так не заблукаю. В мене ніс.",
            "^night.не_бери На всіх? То ше гірше. Нахаба.",
            "^night.не_бери Беру. Я все беру до серця. І до дзьоба.",
            "^night.шия Притулюсь. Але це нічо не значить, ясно?",
            "^night.шия До шиї? Там {name} лоскотно. Ну й хай.",
            "^night.вогонь Скоро — то коли? Бо я в бурульку перетворююсь.",
            "^night.вогонь Скоро. Ти завжди кажеш «скоро».",
            "^night.миша Поки не зробила. Дзьобну. Шоб знала.",
            "^night.миша Миша — то вечеря, а не друг.",
            "^night.змія Змія? Ну… тоді хай шурхотить собі.",
            "^night.змія Змію я дзьобну двічі. Для певності.",
            "^night.думаю Думай тихіше, бо я чую, як скрипить.",
            "^night.думаю Думаєш? Про мене, сто пудів.",
            "^night.пильную Ну то я покимарю. Ти ж однаково пильнуєш.",
            "^night.пильную Пильнуєш — то пильнуй і мене. Мені нудно.",
            "^night.смачного Дякую. Тобі не лишу.",
            "^night.смачного Свіже — то кожен може. А гниле — з характером.",
            "^night.болото Шкода, бляха. Я б подзьобав.",
            "^night.болото То ходім до болота. Я швидко.",
            "^near_death.весело_болить Болить — то ше веселіше, ге-ге.",
            "^near_death.весело_болить А мені й не болить. Мені смішно, бо ми живі.",
            "^near_death.весело_мовчиш То тобі весело. А мені нудно.",
            "^near_death.весело_мовчиш Не діждешся. Я б на тих похоронах ше й співав.",
