            "^near_death.руки_нескажу О, і ти? То нас уже троє трусунів.",
            "^near_death.руки_нескажу Тримаюсь, бо хочу. Мовчи вже.",
            "^near_death.руки_злість Від злості. Так і запишем. Від злості.",
            "^near_death.руки_злість Від злості, ага. Я ше ту гниду не доклював.",
            "^walk.далеко_мандри Мандри, бля. Скажи ше «пригоди». Тьху.",
            "^walk.далеко_мандри Ага-ага. Аби не по колу, як минулого разу.",
            "^walk.далеко_карта Сподіваєшся. Ну все, ми заблукали.",
            "^walk.далеко_карта В голові? Там же вітер свище, я чув.",
            "^walk.далеко_неный Я не скиглю. Я, бля, коментую. Різниця.",
            "^walk.далеко_неный Мало? То понеси мене сам, раз такий бадьорий.",
            "^walk.гордо_розчулився Не розчулився. Просто… далеко. Відчепись.",
            "^walk.гордо_розчулився Розчулився, ага. Від тряски.",
            "^walk.гордо_нуль Нуль кроків, зате скільки тряски.",
            "^walk.гордо_нуль Я не ногами. Я душею йшов.",
            "^walk.ноги_нахлібник Я сили бережу. Для бійки. Отак.",
            "^walk.ноги_нахлібник Нахлібник — то посада. Я її чесно заслужив.",
            "^walk.ноги_затрьох Ну й нехай. В {нього|неї} ноги довгі, а в мене кривенькі.",
            "^walk.ноги_затрьох За трьох іде — за трьох і годує. Особливо мене.",
            "^walk.трясе_розум То в мене його й не було. Нема чого губити.",
            "^walk.трясе_розум Розум не гріє. Пір'я гріє. От і вибирай.",
            "^walk.трясе_злети Злетіти? Шоб ти тут сам розумничав? Ше чого.",
