            "^walk.пейзаж_дивитись Вмію. Дивлюсь — дерево. Он, знову дерево.",
            "^walk.пейзаж_дивитись Дивлюсь. Бачу тебе. Краще б не вмів.",
            "^walk.пейзаж_камінь Сам ти камінь. Тупий і сірий.",
            "^walk.пейзаж_камінь Гарний камінь. Здоровий. Значить, і голова гарна.",
