            "^idle_c.чує Ой. Ну… я не ржу. Я кашляю.",
            "^idle_c.стежив Стежив він. За мною теж стежив — і я двічі в болото влетів.",
            "^idle_c.стежив Ну-ну. Подивимось, хто з нас ржатиме останнім.",
            "^idle_c.уламки Шо, серйозно? Ну, тоді хай стоїть. Поки ми не злізем.",
            "^idle_c.уламки Я вилечу раніше. Я швидкий, {м_слівце}.",
            "^idle_c.зуб Нема — то й програти не страшно. Розумно ж?",
            "^idle_c.зуб Тоді дзьоб поставлю. Дзьоб є.",
            "^idle_c.з_нами З нами? Я тіко шо чув, як {він|вона} тебе дурнем назва{в|ла}.",
            "^idle_c.з_нами То хай би й нам шось сказа{в|ла}. Нормальне.",
            "^idle_c.лаєшся Я не матюкаюсь, {м_слівце}. Я так розмовляю. Розумієш різницю?",
            "^idle_c.лаєшся Ото й балакай з {ним|нею}. А я послухаю, як ти зануджуєш.",
            "^idle_c.голосніше Я з тобою балакаю! Просто ти не слухаєш.",
            "^idle_c.голосніше Голосніше, бо тихо ти не чуєш, ботан.",
            "^idle_c.мухи Мухи — то не тролі, професоре. Вкурив?",
            "^idle_c.мухи Бо мухи дурні. Як ти.",
            "^idle_c.крила Я махаю красиво. Ти просто не шариш.",
            "^idle_c.крила Крилами, бля, хоч літають. А мечем шо?",
            "^idle_c.святий Ой, все. Святий, бля, знайшовся.",
            "^idle_c.святий Ліс не скаржився. Тіко ти.",
            "^idle_c.матюк Матюк — то і є думка. Коротка.",
            "^idle_c.матюк Шо, я знов винен? Я тіко правду кажу.",
            "^idle_c.запишу Тіко спробуй ляпнути, {м_слівце}. Тіко спробуй.",
            "^idle_c.запишу Запишеш — я з'їм. Разом з пером.",
            "^idle_c.день Запам'ятовувати — то моя робота. Тобі не дам.",
            "^idle_c.день Не було такого. Тобі приснилось.",
            "^idle_c.коліна Є коліна! Просто сховані. Під пір'ям.",
            "^idle_c.коліна Нема — то по пузо. Різниця невелика.",
            "^idle_c.разом Тепліше, ага. Тіко не розкисай, засранцю.",
            "^idle_c.разом Ну от. Тепер нас двоє дурних.",
            "^idle_c.пісня Знаю! Це коли хтось виє і не соромиться.",
            "^idle_c.пісня Пісня — це коли про пиво і бійку. А це — нудьга.",
            "^idle_c.не_ти Аби не я? Та я співаю, як бог, {м_слівце}! Як Браґі!",
            "^idle_c.не_ти Ну й не проси потім, шоб я заспівав.",
            "^idle_c.працює Я теж працюю! Я… дивлюсь, шоб {name} не вкрали.",
            "^idle_c.працює За трьох — то хай і мені третину дає.",
            "^idle_c.трескаєш Трескаю, бо не дають. Дали б — їв би культурно.",
            "^idle_c.трескаєш Ну і трескаю. Зате з душею.",
            "^idle_c.хроплю Я не хроплю. Я вві сні гарчу. Грізно.",
            "^idle_c.хроплю Де ти троля чув? Брешеш і не червонієш.",
            "^idle_c.живий Живе, живе. А мені під те хропіння не спиться.",
            "^idle_c.живий Ну, тоді хай хропе голосніше. Шоб я знав.",
            "^idle_c.вчаться Навчився! Я дзьобом тебе вчу, ти ж бачиш.",
            "^idle_c.вчаться Сам ти не навчився. Ти книжки читаєш, а не мацаєш.",
            "^idle_c.цікаво А мені цікаво, як тебе обскубти. Кожну пір'їну.",
            "^idle_c.цікаво Цікаво. Шо в тебе в голові, крім книжок. Нічо, мабуть.",
            "^perch_b.сидиш Я сиджу, як орел! Це палиця кривляється.",
            "^perch_b.сидиш Сам ти криво сидиш. І думаєш криво.",
            "^perch_b.погляд Погляд у мене бойовий. А палиця крива.",
            "^perch_b.погляд Ну то й сиди на своїй рівній. Я — на кривій.",
            "^perch_b.користь Користь, бля. Я від тої користі вже дубію.",
            "^perch_b.користь Ото як посиджу спокійно — тобі першому не поздоровиться.",
            "^perch_b.сила Та набралась уже. Аж пре. Пусти полетіти.",
            "^perch_b.сила Сила, сила… Пузо від неї не наїдається.",
            "^perch_b.перо Порахував. Двох нема. То ти їх поцупив?",
            "^perch_b.перо До десяти дорахував, далі нудно.",
            "^perch_b.гуркіт Гуркіт — то найкраща частина.",
            "^perch_b.гуркіт Без плану — то по-нашому. Я б так само.",
            "^perch_b.міст Міст через болото — то був шедевр, не пизди.",
            "^perch_b.міст О, то був кайф. Я з того мосту тричі падав.",
            "^perch_b.тиша_ти Ото й добре, шо заговорив. Я тиші не люблю.",
            "^perch_b.тиша_ти Ше слово — і клюну тебе. Ти тут один.",
            "^perch_b.клюй Жердину жалко. Тебе — ні.",
            "^perch_b.клюй Жердина не пищить. А ти пищиш. Цікавіше.",
            "^perch_b.мудрий Мудрий, бля. Мудрі хоч розповідають шось.",
            "^perch_b.мудрий Мовчиш — то вже наполовину спиш. Прокидайсь.",
            "^perch_b.дурних Ото й розважай дурня. Ти ж розумний.",
            "^perch_b.дурних Дурний, зате не сплю.",
            "^perch_b.будильник Будь ласка. Тепер розкажи шось.",
            "^perch_b.будильник Отож. Нема спати, коли мені нудно.",
            "^perch_b.заслуговую Заслуговуєш ти дзьоба в бік.",
            "^perch_b.заслуговую Заслужив він. Ану посунься, бо штовхну.",
            "^perch_b.першим Здається тобі. Я тут з ранку.",
            "^perch_b.першим Хто перший — той перший і злетить. Від мене.",
            "^perch_b.самолюбство Самолюбство в мене нормальне. Як і дупа.",
            "^perch_b.самолюбство Ото й посунься, раз така вузька.",
            "^perch_b.зіпсуй Не зіпсую. Хіба трошки.",
            "^perch_b.зіпсуй Я? Зіпсую? Я тут найкраще, шо є.",
            "^perch_b.цінуй Ціную. Тіко не дивись так.",
            "^perch_b.цінуй Ціную, ціную. Чо ти завівся.",
            "^perch_b.бурчав Бурчав, бо міг. І ше буду.",
            "^perch_b.бурчав Чуєш ти. Вуха б тобі заткнути.",
            "^perch_b.ніжно Ніжно?! Я ж навіть матюкнувся. Ну, подумки.",
            "^perch_b.ніжно Тіко спробуй розчулитись — дзьобну.",
            "^perch_b.віддам Ото й домовились. Тіко нікому.",
            "^perch_b.віддам І правильно. Бо я б і тебе за {нього|неї} віддав.",
            "^perch_b.ой Ото й попався, ботан. Я все чув.",
            "^perch_b.ой Сказав же. Ну все, назад не забереш.",
            "^perch_b.мякнеш Я не м'якну. Я… розслабився.",
            "^perch_b.мякнеш Хай чують. Я ж і дзьобнути можу.",
            "^perch_b.чемно Чемно, бля. Я чемно попрошу. Дзьобом у п'яту.",
            "^perch_b.чемно Ну то ти попроси. Ти ж у нас чемний.",
            "^perch_b.принесе Ото хай про мене не забуде. Першим.",
            "^perch_b.принесе Ну, як принесе — я перший. Ти ше подумаєш.",
            "^perch_b.спробуй Пробував. Голова болить. Нахуй таке.",
            "^perch_b.спробуй Раз на рік я вже думав. Цього року — все.",
            "^perch_b.пика Дзьоб, пика — яка різниця. Видно ж.",
            "^perch_b.пика Ото й не думай так голосно.",
            "^perch_b.гризти Я шо, бобер? Хоча… трошки можна.",
            "^perch_b.гризти Не буду. Хіба лизну. Раз.",
            "^perch_b.запамятаю Тіко спробуй комусь розказати.",
            "^perch_b.запамятаю Запам'ятовувати — моя робота, ботан.",
            "^perch_b.замишляєш Нічо я не замишляю. Поки шо.",
            "^perch_b.замишляєш Замишляю. Як тебе з жердини зіпхнути.",
            "^perch_b.крізь Ото й дивись крізь. Тіко мовчки.",
            "^perch_b.крізь Шо там цікавого? Кущ?",
            "^perch_b.думка Думка він. А я — пам'ять. І пам'ять каже: всяке бува.",
            "^perch_b.думка Ну, раз знаєш — то й добре. Я так, на всяк.",
            "^perch_b.нікуди Отож. Куди ж ми дінемось.",
            "^perch_b.нікуди Ото й добре. Бо шукати лінь.",
            "^perch_b.дзьобнеш Дзьобну. Ласкаво. Двічі.",
            "^perch_b.дзьобнеш А то. Шоб пам'ята{в|ла}.",
            "",
            "@м_бос",
            "^boss.пишаюся>boss.пишаюся_розкис Ого. Хугін розкис. Запишіть хтось, бо ніхто не повірить.",
            "^boss.пишаюся>boss.пишаюся_ще_раз Всіма? І мною? Скажи ше раз, бо я не розчув.",
            "~3 ^boss.пишаюся>boss.пишаюся_нікому Я теж, ботан. Тіко нікому, ясно?",
            "^boss.шрами>boss.шрами_загояться Подряпини загояться. А {boss} — вже ні. Ха!",
            "^boss.шрами>boss.шрами_клював Не лягають, бо ти їх тіко рахуєш. Я клював — і лягло.",
            "^boss.шрами>boss.шрами_пірʼїна Подряпини — то фігня. В мене ось пір'їна вилізла, от де біда.",
            "^boss.тиша>boss.тиша_перднув {boss} лежить, от світ і видихнув. Я теж. І перднув трохи, вибач.",
            "^boss.тиша>boss.тиша_нудно Тиша, тиша… Нудно, курва. Давай наступного.",
            "^boss.пісня>boss.пісня_рядок Перший рядок: «Мунін завалив {boss_gen}». А решта — хуйня, не важлива.",
            "^boss.пісня>boss.пісня_мʼясо Пісні — для слабаків. Нам — м'ясо.",
            "^boss.пісня>boss.пісня_кажи Ну? Кажи вже той рядок, шо ти тягнеш?",
            "^boss.погляд>boss.погляд_повчиться Хай дивиться. Хай повчиться, як треба.",
            "^boss.погляд>boss.погляд_шия Відчуваєш? То в тебе шия затерпла, ботан.",
            "^boss.біль>boss.біль_ми_ні Нічо, загоїться. Головне — {boss} лежить, а ми ні.",
            "^boss.біль>boss.біль_вивалив Дорого? Та норм. Я б і більше вивалив.",
            "~3 ^boss.біль>boss.біль_сядь Ей, {name}, сядь, бляха. Не геройствуй хоч зара.",
            "^boss.наступний>boss.наступний_готовий Та хоч хто. Я готовий, хоч зара.",
            "^boss.наступний>boss.наступний_найбільший Найбільшого давай. Шоб було шо клювати.",
            "^boss.страх>boss.страх_трошки Мені — ні. Ну… трошки. Трошечки. Відчепись.",
            "^boss.страх>boss.страх_теж Страшно, кажеш? Ссикло. Але я теж, якшо чесно.",
            "",
            "@м_смерть",
            "^death.повернувся>death.повернувся_мерзли Поверну{вся|лась}, а ми тут мерзли, як дурні.",
            "^death.речі>death.речі_зʼїм Хто спиздить — того я з'їм. Живцем.",
            "^death.речі>death.речі_геройство Підем. Тіко цього разу без геройства, бо знов ляжемо.",
            "^death.ліжко>death.ліжко_голий Після пиятики хоч весело було. А тут — голова болить і голий.",
            "^death.ліжко>death.ліжко_логіка Ліжко — то добре. Могила — гірше. Логіка, ботан.",
            "^death.валькірії>death.валькірії_пірʼя Я б їм пір'я повискубував, курвам крилатим.",
            "^death.валькірії>death.валькірії_ненас Хай кружляють. Хуй їм, а не нас.",
            "^death.помилка>death.помилка_непопередив Помилка — шо ти, розумник, не попередив.",
            "^death.помилка>death.помилка_name Помилка — то {name}. Завжди. Без варіантів.",
            "^death.помилка>death.помилка_кажи Ну? Кажи вже, раз такий умний.",
            "^death.могила>death.могила_цвинтар Колекція, бля. Скоро свій цвинтар відкриємо, з табличкою.",
            "^death.могила>death.могила_памʼятник Хай стоїть. Пам'ятник дурості. Нашій.",
            "^death.холод>death.холод_нехочу Холодно, темно й нудно, як у дупі. Більше туди не хочу.",
            "^death.холод>death.холод_сидів Та я не лежав. Я сидів і чекав, ясно?",
            "^death.помста>death.помста_очі Пошкодує, гнида. Я тій гниді очі виклюю. Обидва.",
            "^death.помста>death.помста_пика Пику я вже запам'ятав. Хай тепер ховається.",
            "^death.знову>death.знову_злий З нуля, бля. Голий, босий і злий як собака.",
            "^death.знову>death.знову_памʼятаємо Та не з нуля. Ми ж пам'ятаємо. Я — то точно.",
            "",
            "@м_біом",
            "^biome.страшно>biome.страшно_я_тут Страшно? Я тут, ботан. Хай тіко шось ворухнеться.",
            "^biome.страшно>biome.страшно_гарно2 Гарне, бляха. Тіко нікому не кажи, шо я сказав.",
            "^biome.звірі>biome.звірі_спершуя Жеруть, ага. Але спершу я їх.",
            "^biome.звірі>biome.звірі_вкурсі Тутешні ше не в курсі, хто прийшов, {м_слівце}. Зара будуть.",
            "^biome.мапа>biome.мапа_відступаю Тікати? Я не тікаю. Я красиво відступаю. Шариш?",
            "^biome.мапа>biome.мапа_смачний Ти малюй свою мапу. А я гляну, хто тут найсмачніший.",
            "^biome.небо>biome.небо_гівняний Колір як колір. Гівняний якийсь.",
            "^biome.небо>biome.небо_синє Іншого? Та воно ж синє, як і було. Ти шо, сліпий?",
            "^biome.рослини>biome.рослини_зжер Пізно, я вже зжер. Нічо, живий. Поки шо.",
            "^biome.рослини>biome.рослини_нежеру Та не жеру, не жеру. Поки шо.",
            "^biome.перші>biome.перші_наше Перші — значить, усе наше. Все, чуєш?",
            "^biome.перші>biome.перші_дурні Перші, бо інші не такі дурні, як ми.",
            "^biome.тиша>biome.тиша_знають Насторожено, бо знають, шо я прийшов. І правильно.",
            "^biome.тиша>biome.тиша_буря Тиша, бля. Перед бурею, по-любому.",
            "^biome.дім>biome.дім_нудно Чую. І заїбісь. Там нудно було.",
            "^biome.дім>biome.дім_жерти Дім, дім… Там хоч жерти було шо.",
            "^biome.скарби>biome.скарби_мої Скарби — мої. Хто перший урвав — той і бере.",
            "^biome.скарби>biome.скарби_показуй Цінне? Де?! Де, курва? Показуй!",
            "",
            "@м_вогонь",
            "^rest_a.дражню>rest_a.мороз Я до вогню лізу, бо від твоїх жартів аж мороз по пір'ю.",
            "^rest_a.подобається>rest_a.нікому Нікому не скажу. Тіко всім, {м_слівце}. Гиги.",
            "^rest_a.подобається>rest_a.мені_теж Та й мені, бля. Тіко ти теж мовчи, ясно?",
            "^rest_a.казка>rest_a.дзьоб А тоді прилетів інший ворон і дав тому розумнику в дзьоб. Кінець. Гарна казка.",
            "^rest_a.казка>rest_a.допер Та я вже допер, хто. Казка — гівно, {м_слівце}.",
            "^rest_a.іскри>rest_a.жар Світлячки? То жар, дурню. Сунь туди дзьоба — сам дізнаєшся.",
            "^rest_a.іскри>rest_a.хвіст Гарно, {м_слівце}. Аби тіко на хвіст мені не сіли.",
            "^rest_a.завтра>rest_a.пика Куди поведе — там комусь і наб'ємо пику. Просто.",
            "^rest_a.завтра>rest_a.гель Та хоч у Гель. Аби там годували.",
            "^rest_a.зорі>rest_a.дим Мерехтять, бо дим, романтик ти пернатий.",
            "^rest_a.зорі>rest_a.мовчи Гарно, бля. Мовчи. Не псуй.",
            "^rest_a.мрія>rest_a.махач А я — про махач і повну миску. Ну і медовухи бочку.",
            "^rest_a.мрія>rest_a.ссикуни Миска — то добре. А дах — для ссикунів.",
            "^rest_a.одін>rest_a.бухає Сидить і бухає. Як завжди, старий.",
            "^rest_a.одін>rest_a.думає Сидить і про нас думає. Ну, про мене. Про тебе шо там думати.",
            "^rest_a.пісня>rest_a.спробуй Тіко спробуй, {м_слівце}. Тіко рота відкрий.",
            "^rest_a.пісня>rest_a.засну Співай. Я засну — і всім буде краще.",
            "^rest_a.день>rest_a.нудний Довгий і нудний, бляха. Але вогонь — норм вогонь.",
            "^rest_a.день>rest_a.каторга Закінчився, бо я заїбався. Не день, а каторга.",
            "",
            "@м_вогонь_почин",
            "^rest_b.історія Хугін, розкажи шось. Тіко не про мудрість, {м_слівце}, бо засну.",
            "^rest_b.жарина Жарина вистрибнула! Мало хвоста мені не підсмалила, курва.",
            "^rest_b.нудно Нудно, {м_слівце}. Пішли когось уб'ємо, га?",
            "^rest_b.смажене Смаженим пахне. Нам шось лишиться чи як?",
            "^rest_b.ворони А інші ворони зара теж біля вогню? Чи мерзнуть десь, бідолахи?",
            "",
        };
    }
}
#endif
